const BlokusBoard = ({ room, gameState, mySeatNo, onAction }) => {
  const [selectedPieceCode, setSelectedPieceCode] = useState("");
  const [rotation, setRotation] = useState(0);
  const [flipped, setFlipped] = useState(false);
  const [hoverCell, setHoverCell] = useState(null);
  const [anchorCell, setAnchorCell] = useState(null);
  const [boardCellSize, setBoardCellSize] = useState(defaultBlokusBoardCellSize);
  const boardSize = Number(get(gameState, "board_size", "boardSize", 20));
  const duoRule = Boolean(get(gameState, "duo_rule", "duoRule", false));
  const variantCode = get(gameState, "variant_code", "variantCode", "BASE");
  const currentColor = get(gameState, "current_color", "currentColor", null);
  const currentSeatNo = Number(get(gameState, "current_seat_no", "currentSeatNo", 0));
  const phase = gameState?.phase || "PLAYING";
  const colors = get(gameState, "colors", "colors", []);
  const pieces = get(gameState, "pieces", "pieces", []);
  const scores = get(gameState, "scores", "scores", []);
  const board = get(gameState, "board", "board", []);
  const startPoints = get(gameState, "start_points", "startPoints", []);
  const moveHistory = get(gameState, "move_history", "moveHistory", []);
  const currentColorState = colors.find((item) => item.color === currentColor);
  const currentColorShared = Boolean(get(currentColorState, "shared", "shared", false));
  const currentColorControllers = get(currentColorState, "controller_seat_nos", "controllerSeatNos", []);
  const roomPlayers = playersOf(room);
  const playerName = (seatNo) => roomPlayers.find((player) => seatNoOf(player) === Number(seatNo))?.nickname || `${seatNo}번`;
  const currentTurnLabel = phase === "FINISHED"
    ? "게임 종료"
    : currentColorShared
      ? `${currentColorState?.label || "-"} 공유 색 · 이번 담당 ${playerName(currentSeatNo)}`
      : `${currentColorState?.label || "-"} 차례 · ${mySeatNo === currentSeatNo ? "내 차례" : playerName(currentSeatNo)}`;
  const variantNotice = variantCode === "THREE_PLAYER"
    ? "3인 변형 · 초록은 세 플레이어가 돌아가며 두는 공유 색이며, 최종 점수에는 각자의 파랑/노랑/빨강만 반영됩니다."
    : variantCode === "TWO_PLAYER"
      ? "2인 변형 · 1번은 파랑+빨강, 2번은 노랑+초록을 번갈아 조종하고 두 색 점수를 합산합니다."
      : variantCode === "TEAM"
        ? "2대2 팀전 · 마주 보는 파랑+빨강, 노랑+초록의 점수를 합산합니다."
        : duoRule
          ? "듀오 · 14x14 보드의 두 중앙 시작점에서 시작하고 파랑/노랑만 사용합니다."
          : "";
  const remainingPieceCodes = get(currentColorState, "remaining_piece_codes", "remainingPieceCodes", []);
  const pieceByCode = useMemo(() => {
    const next = new Map();
    pieces.forEach((piece) => next.set(piece.code, piece));
    return next;
  }, [pieces]);
  const selectedPiece = pieceByCode.get(selectedPieceCode);
  const occupied = useMemo(() => {
    const next = new Map();
    board.forEach((cell) => next.set(`${cell.x}:${cell.y}`, cell));
    return next;
  }, [board]);
  const colorByCell = useMemo(() => {
    const next = new Map();
    board.forEach((cell) => next.set(`${cell.x}:${cell.y}`, cell.color));
    return next;
  }, [board]);
  const colorsOnBoard = useMemo(() => new Set(board.map((cell) => cell.color)), [board]);
  const startPointByCell = useMemo(() => {
    const next = new Map();
    startPoints.forEach((point) => next.set(`${Number(point.x)}:${Number(point.y)}`, point));
    return next;
  }, [startPoints]);
  const placementAnchor = anchorCell || hoverCell;
  const hoverCells = useMemo(() => {
    if (!placementAnchor || !selectedPiece || phase !== "PLAYING") return [];
    return transformCells(selectedPiece, rotation, flipped, placementAnchor.x, placementAnchor.y);
  }, [placementAnchor, selectedPiece, rotation, flipped, phase]);
  const placementStatus = useMemo(() => {
    if (!hoverCells.length || !currentColor) return { legal: false, reason: "" };
    return blokusPlacementStatus({ cells: hoverCells, boardSize, occupied, colorByCell, colorsOnBoard, color: currentColor, startPoints });
  }, [hoverCells, boardSize, occupied, colorByCell, colorsOnBoard, currentColor, startPoints]);
  const currentColorFirstPiece = Boolean(currentColor) && !colorsOnBoard.has(currentColor);
  const placementSignals = useMemo(() => {
    if (!hoverCells.length || !currentColor) {
      return {
        outOfBounds: false,
        overlap: false,
        sideContact: false,
        cornerContact: false,
        coversStart: false,
      };
    }
    const orthogonal = [[1, 0], [-1, 0], [0, 1], [0, -1]];
    const diagonal = [[1, 1], [1, -1], [-1, 1], [-1, -1]];
    const validStartPoints = (startPoints || []).filter((point) => !get(point, "color", "color", null) || get(point, "color", "color", null) === currentColor);
    const fallbackCorner = blokusStartCorners[currentColor];
    return {
      outOfBounds: hoverCells.some((cell) => cell.x < 0 || cell.y < 0 || cell.x >= boardSize || cell.y >= boardSize),
      overlap: hoverCells.some((cell) => occupied.has(`${cell.x}:${cell.y}`)),
      sideContact: hoverCells.some((cell) => orthogonal.some(([dx, dy]) => colorByCell.get(`${cell.x + dx}:${cell.y + dy}`) === currentColor)),
      cornerContact: hoverCells.some((cell) => diagonal.some(([dx, dy]) => colorByCell.get(`${cell.x + dx}:${cell.y + dy}`) === currentColor)),
      coversStart: validStartPoints.length
        ? validStartPoints.some((point) => hoverCells.some((cell) => cell.x === Number(point.x) && cell.y === Number(point.y)))
        : Boolean(fallbackCorner && hoverCells.some((cell) => cell.x === fallbackCorner.x && cell.y === fallbackCorner.y)),
    };
  }, [hoverCells, currentColor, startPoints, boardSize, occupied, colorByCell]);
  const legalPlacementCountsByPieceCode = useMemo(() => {
    const next = new Map();
    remainingPieceCodes.forEach((pieceCode) => {
      next.set(pieceCode, blokusLegalPlacementCountForPiece({
        piece: pieceByCode.get(pieceCode),
        boardSize,
        occupied,
        colorByCell,
        colorsOnBoard,
        color: currentColor,
        startPoints,
      }));
    });
    return next;
  }, [remainingPieceCodes, pieceByCode, boardSize, occupied, colorByCell, colorsOnBoard, currentColor, startPoints]);
  const selectedPieceLegalCount = Number(legalPlacementCountsByPieceCode.get(selectedPieceCode) || 0);
  const totalLegalPlacementCount = useMemo(
    () => Array.from(legalPlacementCountsByPieceCode.values()).reduce((sum, count) => sum + count, 0),
    [legalPlacementCountsByPieceCode],
  );
  const firstPlayablePieceCode = useMemo(
    () => remainingPieceCodes.find((pieceCode) => Number(legalPlacementCountsByPieceCode.get(pieceCode) || 0) > 0) || "",
    [remainingPieceCodes, legalPlacementCountsByPieceCode],
  );
  const quickPieceCodes = useMemo(() => {
    const selectedCodes = remainingPieceCodes.includes(selectedPieceCode) ? [selectedPieceCode] : [];
    const otherCodes = remainingPieceCodes
      .filter((pieceCode) => pieceCode !== selectedPieceCode)
      .sort((left, right) => {
        const leftCount = Number(legalPlacementCountsByPieceCode.get(left) || 0);
        const rightCount = Number(legalPlacementCountsByPieceCode.get(right) || 0);
        const playableDelta = Number(rightCount > 0) - Number(leftCount > 0);
        if (playableDelta) return playableDelta;
        if (rightCount !== leftCount) return rightCount - leftCount;
        const leftPiece = pieceByCode.get(left);
        const rightPiece = pieceByCode.get(right);
        return Number(rightPiece?.size || rightPiece?.cells?.length || 0) - Number(leftPiece?.size || leftPiece?.cells?.length || 0);
      });
    return [...selectedCodes, ...otherCodes].slice(0, 8);
  }, [remainingPieceCodes, selectedPieceCode, legalPlacementCountsByPieceCode, pieceByCode]);
  const selectedPieceSize = Number(selectedPiece?.size || selectedPiece?.cells?.length || 0);
  const remainingSquares = useMemo(() => remainingPieceCodes.reduce((sum, pieceCode) => {
    const piece = pieceByCode.get(pieceCode);
    return sum + Number(piece?.size || piece?.cells?.length || 0);
  }, 0), [remainingPieceCodes, pieceByCode]);
  const blokusPiecePressureEntries = useMemo(() => remainingPieceCodes.map((pieceCode) => {
    const piece = pieceByCode.get(pieceCode);
    const legalCount = Number(legalPlacementCountsByPieceCode.get(pieceCode) || 0);
    return {
      pieceCode,
      piece,
      legalCount,
      size: Number(piece?.size || piece?.cells?.length || 0),
    };
  }), [remainingPieceCodes, pieceByCode, legalPlacementCountsByPieceCode]);
  const blokusBlockedPieceCount = blokusPiecePressureEntries.filter((entry) => entry.legalCount <= 0).length;
  const blokusBestPieceEntry = [...blokusPiecePressureEntries]
    .filter((entry) => entry.legalCount > 0)
    .sort((left, right) => {
      if (right.legalCount !== left.legalCount) return right.legalCount - left.legalCount;
      return right.size - left.size;
    })[0] || null;
  const blokusScoreDetailsByColor = useMemo(() => {
    const next = new Map();
    colors.forEach((colorState) => {
      const color = colorState.color;
      const colorRemainingPieceCodes = get(colorState, "remaining_piece_codes", "remainingPieceCodes", []);
      const colorRemainingSquares = colorRemainingPieceCodes.reduce((sum, pieceCode) => {
        const piece = pieceByCode.get(pieceCode);
        return sum + Number(piece?.size || piece?.cells?.length || 0);
      }, 0);
      const completed = colorRemainingPieceCodes.length === 0;
      const lastPieceCode = get(colorState, "last_piece_code", "lastPieceCode", "");
      const shared = Boolean(get(colorState, "shared", "shared", false));
      const controllerSeatNos = get(colorState, "controller_seat_nos", "controllerSeatNos", []);
      const completionBonus = completed ? 15 : 0;
      const monominoBonus = completed && lastPieceCode === "I1" ? 5 : 0;
      const score = Number(get(
        colorState,
        "score",
        "score",
        completed ? completionBonus + monominoBonus : -colorRemainingSquares,
      ));

      next.set(color, {
        color,
        label: get(colorState, "label", "label", blokusColorLabels[color] || color),
        ownerSeatNo: Number(get(colorState, "owner_seat_no", "ownerSeatNo", 0)),
        remainingSquares: colorRemainingSquares,
        completed,
        lastPieceCode,
        completionBonus,
        monominoBonus,
        shared,
        controllerSeatNos,
        score,
      });
    });
    return next;
  }, [colors, pieceByCode]);
  const currentBlokusScoreDetail = currentColor ? blokusScoreDetailsByColor.get(currentColor) : null;
  const previewCells = useMemo(() => {
    if (!hoverCells.length) return new Set();
    return new Set(hoverCells.map((cell) => `${cell.x}:${cell.y}`));
  }, [hoverCells]);
  const myTurn = phase === "PLAYING" && currentSeatNo === mySeatNo;
  const canPass = myTurn && totalLegalPlacementCount === 0;
  const selectedPieceBlocked = myTurn && Boolean(selectedPieceCode) && selectedPieceLegalCount <= 0 && totalLegalPlacementCount > 0;
  const scoreDisplayLabel = (score) => {
    const scoreKey = String(get(score, "score_key", "scoreKey", ""));
    const scoreColors = get(score, "colors", "colors", []);
    const colorText = scoreColors.map((color) => blokusColorLabels[color] || color).join("+");
    if (scoreKey.startsWith("TEAM_")) {
      const seatNos = scoreColors
        .map((color) => blokusScoreDetailsByColor.get(color)?.ownerSeatNo)
        .filter(Boolean);
      const names = [...new Set(seatNos)].map(playerName).join("+");
      return names ? `${names} 팀 (${colorText})` : `${score.label || "팀"} (${colorText})`;
    }
    const seatMatch = scoreKey.match(/^SEAT_(\d+)$/);
    if (seatMatch) {
      const name = playerName(Number(seatMatch[1]));
      return colorText ? `${name} (${colorText})` : name;
    }
    return score.label || scoreKey || "점수";
  };
  const winners = scores.filter((score) => Boolean(get(score, "winner", "winner", false)));
  const winnerText = winners.map(scoreDisplayLabel).join(", ");
  const winningScore = winners.length ? Number(get(winners[0], "score", "score", 0)) : 0;
  const blokusTurnGuidance = (() => {
    if (phase === "FINISHED") {
      return winners.length ? `${winnerText} 승리, 최종 ${winningScore}점입니다.` : "게임이 종료되었습니다.";
    }
    if (!myTurn) {
      return `${playerName(currentSeatNo)}님의 ${currentColorState?.label || currentColor || "색"} 차례를 기다리는 중입니다.`;
    }
    if (canPass) {
      return "남은 모든 조각이 막혔습니다. 패스를 눌러 다음 색으로 넘길 수 있습니다.";
    }
    if (selectedPieceBlocked) {
      return "선택한 조각은 둘 수 없습니다. 자동 선택으로 가능한 조각을 고르거나 다른 조각을 확인하세요.";
    }
    if (anchorCell && placementStatus.legal) {
      return `${anchorCell.x + 1}열 ${anchorCell.y + 1}행 기준으로 놓을 수 있습니다. 다시 누르거나 놓기 버튼으로 확정하세요.`;
    }
    if (anchorCell && !placementStatus.legal) {
      return placementStatus.reason ? `선택 위치는 ${placementStatus.reason} 때문에 둘 수 없습니다.` : "선택 위치에는 둘 수 없습니다. 다른 칸을 골라주세요.";
    }
    return selectedPiece ? "조각을 회전/뒤집은 뒤 보드 칸을 선택하세요." : "먼저 둘 조각을 선택하세요.";
  })();
  const blokusQuickFacts = [
    { label: "색", value: currentColorState?.label || currentColor || "-" },
    { label: "조각", value: selectedPiece?.name || "미선택" },
    { label: "가능", value: `${totalLegalPlacementCount.toLocaleString("ko-KR")}곳` },
    { label: "선택", value: anchorCell ? `${anchorCell.x + 1}, ${anchorCell.y + 1}` : "없음" },
  ];
  const blokusFlowItems = [
    {
      label: "단계",
      value: phase === "FINISHED" ? "게임 종료" : "조각 배치",
      detail: currentTurnLabel,
      icon: "stage",
      tone: phase === "FINISHED" ? "done" : myTurn ? "active" : "neutral",
    },
    {
      label: "색/차례",
      value: currentColorState?.label || currentColor || "-",
      detail: currentColorShared ? `${playerName(currentSeatNo)}님이 공유 색을 조종합니다.` : `${playerName(currentSeatNo)}님의 차례입니다.`,
      icon: "turn",
      tone: myTurn ? "active" : "neutral",
    },
    {
      label: "배치 가능",
      value: `${totalLegalPlacementCount.toLocaleString("ko-KR")}곳`,
      detail: selectedPiece ? `${selectedPiece.name} 가능 위치 ${selectedPieceLegalCount.toLocaleString("ko-KR")}곳 · 남은 칸 ${remainingSquares}칸` : `남은 조각 ${remainingPieceCodes.length}개`,
      icon: "decision",
      tone: canPass ? "danger" : totalLegalPlacementCount > 0 ? "active" : "waiting",
    },
    {
      label: phase === "FINISHED" ? "결과" : "선택 근거",
      value: phase === "FINISHED" && winnerText ? `${winnerText} 승리` : anchorCell ? `${anchorCell.x + 1}, ${anchorCell.y + 1}` : "보드 선택 대기",
      detail: blokusTurnGuidance,
      icon: phase === "FINISHED" ? "win" : "recent",
      tone: phase === "FINISHED" ? "done" : placementStatus.legal ? "active" : "neutral",
    },
  ];
  const placeButtonEnabled = myTurn && Boolean(anchorCell) && Boolean(placementStatus.legal);
  const placeButtonHint = !myTurn
    ? "내 차례가 되면 놓을 수 있습니다."
    : !selectedPiece
      ? "먼저 오른쪽 조각 목록에서 도형을 고르세요."
      : !anchorCell
        ? "보드 칸을 누르면 도형이 덮을 칸이 색으로 표시됩니다."
        : placementStatus.legal
          ? "초록/현재 색 미리보기 칸에 확정 배치할 수 있습니다."
          : placementStatus.reason || "현재 위치에는 놓을 수 없습니다.";

  useEffect(() => {
    if (!remainingPieceCodes.includes(selectedPieceCode)) {
      setSelectedPieceCode(remainingPieceCodes[0] || "");
      setRotation(0);
      setFlipped(false);
      setAnchorCell(null);
    }
  }, [remainingPieceCodes, selectedPieceCode]);

  useEffect(() => {
    setAnchorCell(null);
  }, [selectedPieceCode, rotation, flipped, currentColor]);

  useEffect(() => {
    if (typeof window === "undefined") return;
    if (!blokusBoardCellSizes.includes(boardCellSize)) return;
    window.localStorage?.setItem(blokusBoardCellSizeStorageKey, String(boardCellSize));
  }, [boardCellSize]);

  const selectFirstPlayablePiece = () => {
    if (!firstPlayablePieceCode) return;
    setSelectedPieceCode(firstPlayablePieceCode);
    setRotation(0);
    setFlipped(false);
    setAnchorCell(null);
    setHoverCell(null);
  };

  const place = async (x, y) => {
    if (!myTurn || !selectedPieceCode) return;
    await onAction({
      action_type: "PLACE",
      piece_code: selectedPieceCode,
      anchor_x: x,
      anchor_y: y,
      rotation,
      flipped,
    });
    setAnchorCell(null);
    setHoverCell(null);
  };

  const selectCell = async (x, y) => {
    if (!myTurn || !selectedPieceCode) return;
    const sameAnchor = anchorCell?.x === x && anchorCell?.y === y;
    if (sameAnchor && placementStatus.legal) {
      await place(x, y);
      return;
    }
    setAnchorCell({ x, y });
    setHoverCell(null);
  };

  const pass = async () => {
    if (!myTurn) return;
    await onAction({ action_type: "PASS" });
  };

  return (
    <div className="grid gap-4 xl:grid-cols-[minmax(0,1fr)_360px]">
      <div id="blokus-board-panel" className="scroll-mt-24 rounded-[1.5rem] border border-slate-200 bg-white p-3 shadow-lg sm:p-4">
        <div className="mb-3 flex flex-wrap items-center justify-between gap-2">
          <div className="flex items-center gap-2 text-sm font-black text-slate-900">
            <Shield className="h-4 w-4 text-primary-600" />
            블로커스 보드
          </div>
          {duoRule && (
            <div className="rounded-full bg-indigo-50 px-3 py-1 text-xs font-black text-indigo-700">
              듀오 · 14x14 중앙 시작점
            </div>
          )}
          <div
            className={`rounded-full border px-3 py-1 text-xs font-black ${colorBgSoft[currentColor] || "bg-slate-50"} ${colorText[currentColor] || "text-slate-600"}`}
            role="status"
            aria-live="polite"
            aria-atomic="true"
          >
            {currentTurnLabel}
          </div>
          {myTurn && placementAnchor && (
            <div className={`rounded-full px-3 py-1 text-xs font-black ${placementStatus.legal ? "bg-emerald-100 text-emerald-700" : "bg-rose-100 text-rose-700"}`}>
              {placementStatus.legal ? "배치 가능" : placementStatus.reason || "배치 불가"}
            </div>
          )}
          {myTurn && selectedPiece && !placementAnchor && (
            <div className={`rounded-full px-3 py-1 text-xs font-black ${selectedPieceLegalCount > 0 ? "bg-emerald-100 text-emerald-700" : "bg-rose-100 text-rose-700"}`}>
              선택 조각 가능 위치 {selectedPieceLegalCount.toLocaleString("ko-KR")}곳
            </div>
          )}
          {myTurn && (
            <div className={`rounded-full px-3 py-1 text-xs font-black ${canPass ? "bg-amber-100 text-amber-700" : "bg-slate-100 text-slate-600"}`}>
              전체 가능 위치 {totalLegalPlacementCount.toLocaleString("ko-KR")}곳
            </div>
          )}
        </div>
        <GameFlowMeter
          title="블로커스 배치 흐름"
          detail="현재 색, 선택 조각, 합법 배치 수, 확정 근거를 한 줄 흐름으로 확인합니다."
          items={blokusFlowItems}
          tone={phase === "FINISHED" ? "amber" : myTurn ? "emerald" : "slate"}
          className="mb-3"
          smoke="blokus-flow-meter"
        />
        <BlokusPlacementGuidePanel
          selectedPiece={selectedPiece}
          currentColor={currentColor}
          myTurn={myTurn}
          canPass={canPass}
          anchorCell={anchorCell}
          placementStatus={placementStatus}
          selectedPieceLegalCount={selectedPieceLegalCount}
          totalLegalPlacementCount={totalLegalPlacementCount}
          remainingSquares={remainingSquares}
          firstPiece={currentColorFirstPiece}
          placementSignals={placementSignals}
        />
        <BlokusTerritoryPressurePanel
          currentColor={currentColor}
          selectedPiece={selectedPiece}
          selectedPieceLegalCount={selectedPieceLegalCount}
          totalLegalPlacementCount={totalLegalPlacementCount}
          remainingSquares={remainingSquares}
          remainingPieceCount={remainingPieceCodes.length}
          blockedPieceCount={blokusBlockedPieceCount}
          bestPieceEntry={blokusBestPieceEntry}
          currentScoreDetail={currentBlokusScoreDetail}
          canPass={canPass}
          myTurn={myTurn}
          phase={phase}
        />
        <div className="mb-3 rounded-2xl border border-blue-100 bg-gradient-to-br from-blue-50 via-white to-fuchsia-50 p-3 shadow-sm" role="status" aria-live="polite" aria-atomic="true">
          <div className="flex items-start gap-3">
            <div className={`mt-0.5 rounded-2xl p-2 text-white shadow-sm ${colorClasses[currentColor] || "bg-slate-700"}`}>
              <Shield className="h-4 w-4" />
            </div>
            <div className="min-w-0 flex-1">
              <div className="text-[11px] font-black text-blue-700">지금 할 일</div>
              <div className="mt-0.5 text-sm font-black leading-relaxed text-slate-900">{blokusTurnGuidance}</div>
              <div className="mt-2 grid grid-cols-2 gap-1.5 sm:grid-cols-4">
                {blokusQuickFacts.map((item) => (
                  <div key={item.label} className="rounded-xl bg-white/80 px-2.5 py-2">
                    <div className="text-[10px] font-bold text-slate-400">{item.label}</div>
                    <div className="truncate text-[11px] font-black text-slate-700">{item.value}</div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
        {phase === "FINISHED" && winners.length > 0 && (
          <div className="mb-3 flex flex-wrap items-center justify-between gap-2 rounded-xl border border-amber-200 bg-amber-50 px-3 py-2">
            <div className="flex items-center gap-2 text-sm font-black text-amber-900">
              <Crown className="h-4 w-4 text-amber-500" />
              최종 승자 · {winnerText}
            </div>
            <div className="text-xs font-black text-amber-700">최종 점수 {winningScore}</div>
          </div>
        )}
        {variantNotice && phase !== "FINISHED" && (
          <div className="mb-3 rounded-xl border border-sky-100 bg-sky-50 px-3 py-2 text-xs font-bold leading-relaxed text-sky-800">
            {variantNotice}
            {currentColorShared && currentColorControllers.length > 0 ? ` 현재 공유 색 담당 순서: ${currentColorControllers.map((seatNo) => playerName(seatNo)).join(" → ")}.` : ""}
          </div>
        )}
        <div className="mb-3 flex flex-col gap-2 rounded-xl bg-slate-50 px-3 py-2 sm:flex-row sm:flex-wrap sm:items-center sm:justify-between">
          <div className="grid grid-cols-2 gap-2 sm:flex sm:items-center">
            {blokusBoardCellSizes.map((size) => (
              <button
                key={size}
                type="button"
                className={`min-h-11 rounded-lg px-3 text-xs font-black ${boardCellSize === size ? "bg-slate-900 text-white" : "bg-white text-slate-600"}`}
                onClick={() => setBoardCellSize(size)}
              >
                {size === 16 ? "모바일" : size === 20 ? "촘촘" : size === 24 ? "표준" : "확대"}
              </button>
            ))}
          </div>
          <div className="text-xs font-bold text-slate-500">
            {anchorCell ? `선택 ${anchorCell.x + 1}, ${anchorCell.y + 1}` : "위치 미선택"}
          </div>
        </div>
        <div className="tabletop-board-scroll overflow-auto rounded-xl border border-slate-300 bg-slate-200">
          <div
            className="grid"
            aria-label="블로커스 보드"
            style={{
              gridTemplateColumns: `repeat(${boardSize}, ${boardCellSize}px)`,
              width: boardSize * boardCellSize,
              height: boardSize * boardCellSize,
            }}
            onMouseLeave={() => {
              if (!anchorCell) setHoverCell(null);
            }}
          >
            {Array.from({ length: boardSize * boardSize }, (_, index) => {
              const x = index % boardSize;
              const y = Math.floor(index / boardSize);
              const cell = occupied.get(`${x}:${y}`);
              const color = cell?.color;
              const preview = previewCells.has(`${x}:${y}`);
              const anchored = anchorCell?.x === x && anchorCell?.y === y;
              const startPoint = startPointByCell.get(`${x}:${y}`);
              const cellLabelParts = [`${x + 1}열 ${y + 1}행`];
              if (cell) {
                cellLabelParts.push(`${blokusColorLabels[color] || color} 조각`);
              } else if (startPoint) {
                cellLabelParts.push("시작점");
              } else {
                cellLabelParts.push("빈 칸");
              }
              if (anchored) cellLabelParts.push("현재 선택 위치");
              if (preview && !cell) cellLabelParts.push(placementStatus.legal ? "배치 미리보기 가능" : placementStatus.reason || "배치 미리보기 불가");
              if (preview && cell) cellLabelParts.push("이미 차지한 칸과 겹침");
              if (myTurn && selectedPiece) cellLabelParts.push(`${selectedPiece.name || selectedPieceCode} 배치 기준`);
              const cellLabel = cellLabelParts.join(" · ");
              return (
                <button
                  key={`${x}:${y}`}
                  type="button"
                  className={[
                    "relative border border-white/60 transition-all",
                    color ? `${colorClasses[color] || "bg-slate-500"} shadow-inner` : startPoint ? "bg-amber-100 hover:bg-amber-200" : "bg-slate-50 hover:bg-slate-100",
                    preview && !cell && placementStatus.legal ? `${colorClasses[currentColor] || "bg-slate-400"} z-10 scale-105 opacity-95 ring-2 ring-slate-950 ring-offset-1 ring-offset-white shadow-[0_0_0_2px_rgba(255,255,255,0.9)_inset]` : "",
                    preview && !cell && !placementStatus.legal ? "z-10 scale-105 bg-rose-300 ring-2 ring-rose-700 ring-offset-1 ring-offset-white" : "",
                    preview && cell ? "z-10 ring-2 ring-rose-700 ring-offset-1 ring-offset-white" : "",
                    anchored ? "z-20 ring-2 ring-slate-950 ring-offset-2 ring-offset-amber-200" : "",
                  ].join(" ")}
                  style={{ width: boardCellSize, height: boardCellSize }}
                  onMouseEnter={() => {
                    if (!anchorCell) setHoverCell({ x, y });
                  }}
                  onFocus={() => {
                    if (!anchorCell) setHoverCell({ x, y });
                  }}
                  onClick={() => selectCell(x, y).catch(() => notifyError("둘 수 없는 위치입니다."))}
                  aria-label={cellLabel}
                  aria-pressed={anchored}
                  title={cellLabel}
                >
                  {startPoint && !cell && (
                    <span className="absolute left-1/2 top-1/2 h-2.5 w-2.5 -translate-x-1/2 -translate-y-1/2 rounded-full bg-amber-500 shadow-sm" />
                  )}
                  {preview && !cell && (
                    <span className={`absolute inset-[22%] rounded-[3px] border ${placementStatus.legal ? "border-white/90 bg-white/25" : "border-rose-900/70 bg-white/20"}`} />
                  )}
                </button>
              );
            })}
          </div>
        </div>
        <div id="blokus-action-strip" className="tabletop-mobile-action-strip sticky z-20 mt-3 scroll-mt-24 rounded-2xl border border-slate-200 bg-white/95 p-3 shadow-xl backdrop-blur xl:hidden">
          <div className="mb-2 flex flex-wrap items-center justify-between gap-2 text-[11px] font-bold text-slate-500">
            <span className="font-black text-slate-800">{selectedPiece?.name || "조각 선택"}</span>
            <span>{anchorCell ? `선택 ${anchorCell.x + 1}, ${anchorCell.y + 1}` : "보드에서 위치 선택"}</span>
            <span className={selectedPieceLegalCount > 0 ? "text-emerald-600" : "text-rose-600"}>
              가능 위치 {selectedPieceLegalCount.toLocaleString("ko-KR")}
            </span>
          </div>
          <div className="mb-2 grid grid-cols-[auto_auto_minmax(0,1fr)] gap-2">
            <button
              type="button"
              className="inline-flex h-12 w-12 items-center justify-center rounded-xl bg-slate-100 text-slate-700 disabled:opacity-40"
              onClick={() => setRotation((value) => (value + 90) % 360)}
              disabled={!myTurn}
              aria-label={`선택 조각을 90도 회전합니다. 현재 ${rotation}도`}
              title="회전"
            >
              <RotateCw className="h-4 w-4" />
            </button>
            <button
              type="button"
              className="inline-flex h-12 w-12 items-center justify-center rounded-xl bg-slate-100 text-slate-700 disabled:opacity-40"
              onClick={() => setFlipped((value) => !value)}
              disabled={!myTurn}
              aria-label={`선택 조각을 뒤집습니다. 현재 ${flipped ? "뒤집힌 상태" : "기본 방향"}`}
              title="뒤집기"
            >
              <FlipHorizontal className="h-4 w-4" />
            </button>
            <div className="tabletop-scroll-rail flex min-w-0 gap-2 overflow-x-auto pb-1">
              {quickPieceCodes.map((pieceCode) => {
                const piece = pieceByCode.get(pieceCode);
                const selected = pieceCode === selectedPieceCode;
                const legalCount = Number(legalPlacementCountsByPieceCode.get(pieceCode) || 0);
                return (
                  <button
                    key={`quick-${pieceCode}`}
                    type="button"
                    className={`flex h-16 min-w-[78px] flex-col items-center justify-between rounded-xl border px-2 py-1.5 text-[10px] font-black transition ${selected ? "border-slate-900 bg-slate-900 text-white" : legalCount > 0 ? "border-emerald-100 bg-emerald-50 text-emerald-800" : "border-slate-200 bg-white text-slate-500"}`}
                    onClick={() => setSelectedPieceCode(pieceCode)}
                    disabled={!myTurn}
                    aria-pressed={selected}
                    aria-label={`${piece?.name || pieceCode} 조각 선택 · ${piece?.size || piece?.cells?.length || 0}칸 · 가능 위치 ${legalCount.toLocaleString("ko-KR")}곳${selected ? " · 현재 선택됨" : ""}`}
                    title={`${piece?.name || pieceCode} · 가능 위치 ${legalCount.toLocaleString("ko-KR")}곳`}
                  >
                    <span className="max-w-full truncate">{piece?.name || pieceCode}</span>
                    <BlokusPieceArt piece={piece} color={currentColor || "BLUE"} className="h-7 max-w-full" />
                  </button>
                );
              })}
              {!quickPieceCodes.length && (
                <div className="min-w-[220px]">
                  <BlokusRemainingPiecesEmptyPanel
                    currentColor={currentColor || "BLUE"}
                    colorLabel={currentColorState?.label || currentColor || "현재 색"}
                    currentTurnLabel={currentTurnLabel}
                    canPass={canPass}
                    myTurn={myTurn}
                    currentScoreDetail={currentBlokusScoreDetail}
                    totalLegalPlacementCount={totalLegalPlacementCount}
                    compact
                  />
                </div>
              )}
            </div>
          </div>
          <div className="grid grid-cols-[1fr_auto] gap-2">
            <button
              type="button"
              className={`inline-flex min-h-11 items-center justify-center gap-2 rounded-xl px-3 py-3 text-sm font-black text-white ${placeButtonEnabled ? "bg-emerald-600 shadow-lg shadow-emerald-200" : "bg-slate-400 opacity-70"}`}
              disabled={!placeButtonEnabled}
              onClick={() => anchorCell && place(anchorCell.x, anchorCell.y).catch(() => notifyError("놓을 수 없는 위치입니다."))}
            >
              <CheckCircle2 className="h-4 w-4" />
              놓기
            </button>
            <button
              type="button"
              className="inline-flex min-h-11 items-center justify-center rounded-xl bg-slate-100 px-3 py-3 text-xs font-black text-slate-700 disabled:opacity-40"
              onClick={() => pass().catch(() => notifyError("아직 놓을 수 있는 조각이 있습니다."))}
              disabled={!canPass}
            >
              패스
            </button>
          </div>
          <div className={`mt-2 rounded-xl px-3 py-2 text-[11px] font-bold ${canPass ? "bg-amber-50 text-amber-700" : "bg-slate-50 text-slate-500"}`}>
            {canPass ? "남은 모든 조각이 막혀 패스할 수 있습니다." : placeButtonHint}
          </div>
          {selectedPieceBlocked && (
            <button
              type="button"
              className="mt-2 inline-flex w-full min-h-11 items-center justify-center rounded-xl bg-emerald-50 px-3 py-2 text-xs font-black text-emerald-700"
              onClick={selectFirstPlayablePiece}
            >
              둘 수 있는 조각 자동 선택
            </button>
          )}
        </div>
      </div>

      <aside className="space-y-4">
        <div className="rounded-[1.5rem] border border-slate-200 bg-white p-4 shadow-lg">
          <div className="flex items-center justify-between gap-2">
            <div className="text-sm font-black text-slate-900">조각 선택</div>
            <div className="flex gap-1">
              <button
                type="button"
                className="inline-flex h-11 w-11 items-center justify-center rounded-xl bg-slate-100 text-slate-700 disabled:opacity-40"
                onClick={() => setRotation((value) => (value + 90) % 360)}
                disabled={!myTurn}
                aria-label={`선택 조각을 90도 회전합니다. 현재 ${rotation}도`}
                title="회전"
              >
                <RotateCw className="h-4 w-4" />
              </button>
              <button
                type="button"
                className="inline-flex h-11 w-11 items-center justify-center rounded-xl bg-slate-100 text-slate-700 disabled:opacity-40"
                onClick={() => setFlipped((value) => !value)}
                disabled={!myTurn}
                aria-label={`선택 조각을 뒤집습니다. 현재 ${flipped ? "뒤집힌 상태" : "기본 방향"}`}
                title="뒤집기"
              >
                <FlipHorizontal className="h-4 w-4" />
              </button>
            </div>
          </div>
          <div className="mt-3 flex items-center justify-between rounded-xl bg-slate-50 px-3 py-2 text-xs font-bold text-slate-500">
            <span>회전 {rotation}도</span>
            <span>{flipped ? "뒤집힘" : "기본 방향"}</span>
          </div>
          <div className="mt-3 rounded-xl border border-slate-100 bg-slate-50 p-3">
            <div className="mb-2 flex items-center justify-between gap-2">
              <span className="text-xs font-black text-slate-700">{selectedPiece?.name || "조각"}</span>
              <span className="text-[11px] font-bold text-slate-500">{selectedPiece ? `${selectedPieceSize}칸` : "-"}</span>
            </div>
            <div className="flex min-h-[54px] items-center justify-center rounded-lg bg-white">
              {selectedPiece ? <BlokusPieceArt piece={{ ...selectedPiece, cells: transformCells(selectedPiece, rotation, flipped, 0, 0) }} color={currentColor || "BLUE"} className="h-12 max-w-full" /> : null}
            </div>
          </div>
          <div className={`mt-3 rounded-xl border px-3 py-2 text-xs font-bold leading-relaxed ${selectedPieceLegalCount > 0 ? "border-emerald-100 bg-emerald-50 text-emerald-700" : "border-rose-100 bg-rose-50 text-rose-700"}`}>
            {selectedPiece
              ? selectedPieceLegalCount > 0
                ? `현재 보드에서 이 조각을 둘 수 있는 위치가 ${selectedPieceLegalCount.toLocaleString("ko-KR")}곳 있습니다.`
                : "이 조각은 현재 둘 수 없습니다. 다른 조각을 고르거나 모든 조각이 막혔을 때 패스하세요."
              : "놓을 조각을 선택하세요."}
          </div>
          {selectedPieceBlocked && (
            <button
              type="button"
              className="mt-2 inline-flex w-full items-center justify-center rounded-xl bg-emerald-50 px-3 py-2 text-xs font-black text-emerald-700"
              onClick={selectFirstPlayablePiece}
            >
              둘 수 있는 조각 자동 선택
            </button>
          )}
          <div className="mt-2 grid grid-cols-2 gap-2 text-[11px] font-black">
            <div className="rounded-xl bg-slate-50 px-3 py-2 text-slate-600">남은 조각 {remainingPieceCodes.length}개</div>
            <div className="rounded-xl bg-slate-50 px-3 py-2 text-slate-600">남은 칸 {remainingSquares}칸</div>
            <div className={`col-span-2 rounded-xl px-3 py-2 ${canPass ? "bg-amber-50 text-amber-700" : "bg-slate-50 text-slate-600"}`}>
              전체 가능 위치 {totalLegalPlacementCount.toLocaleString("ko-KR")}곳
            </div>
          </div>
          <button
            type="button"
            className={`mt-3 inline-flex w-full items-center justify-center gap-2 rounded-xl px-3 py-3 text-sm font-black text-white ${placeButtonEnabled ? "bg-emerald-600 shadow-lg shadow-emerald-200" : "bg-slate-400 opacity-70"}`}
            disabled={!placeButtonEnabled}
            onClick={() => anchorCell && place(anchorCell.x, anchorCell.y).catch(() => notifyError("둘 수 없는 위치입니다."))}
          >
            <CheckCircle2 className="h-4 w-4" />
            선택 위치에 놓기
          </button>
          <div className={`mt-2 rounded-xl border px-3 py-2 text-[11px] font-bold leading-relaxed ${placeButtonEnabled ? "border-emerald-100 bg-emerald-50 text-emerald-700" : "border-slate-100 bg-slate-50 text-slate-500"}`}>
            {placeButtonHint}
          </div>
          <div className="mt-3 grid max-h-[360px] grid-cols-2 gap-2 overflow-auto pr-1 sm:grid-cols-3 xl:grid-cols-2">
            {remainingPieceCodes.map((pieceCode) => {
              const piece = pieceByCode.get(pieceCode);
              const selected = pieceCode === selectedPieceCode;
              const legalCount = Number(legalPlacementCountsByPieceCode.get(pieceCode) || 0);
              return (
                <button
                  key={pieceCode}
                  type="button"
                  className={`flex min-h-[82px] flex-col justify-between rounded-xl border p-2 text-left transition ${selected ? "border-slate-900 bg-slate-900 text-white" : legalCount > 0 ? "border-emerald-100 bg-emerald-50 text-emerald-800 hover:border-emerald-300" : "border-slate-200 bg-white text-slate-500 hover:border-slate-400"}`}
                  onClick={() => setSelectedPieceCode(pieceCode)}
                  disabled={!myTurn}
                  aria-label={`${piece?.name || pieceCode} 조각 선택 · ${piece?.size || piece?.cells?.length || 0}칸 · 가능 위치 ${legalCount.toLocaleString("ko-KR")}곳${selected ? " · 현재 선택됨" : ""}`}
                  aria-pressed={selected}
                  title={`${piece?.name || pieceCode} · 가능 위치 ${legalCount.toLocaleString("ko-KR")}곳`}
                >
                  <span className="flex items-center justify-between gap-1 text-[11px] font-black">
                    <span className="min-w-0 truncate">{piece?.name || pieceCode}</span>
                    <span className={`shrink-0 rounded-full px-1.5 py-0.5 text-[9px] ${selected ? "bg-white/15 text-white" : legalCount > 0 ? "bg-white text-emerald-700" : "bg-slate-100 text-slate-400"}`}>
                      {legalCount > 0 ? `${legalCount.toLocaleString("ko-KR")}곳` : "막힘"}
                    </span>
                  </span>
                  <BlokusPieceArt piece={piece} color={currentColor || "BLUE"} className="mt-2 h-8 max-w-full" />
                </button>
              );
            })}
            {!remainingPieceCodes.length && (
              <div className="col-span-2 sm:col-span-3 xl:col-span-2">
                <BlokusRemainingPiecesEmptyPanel
                  currentColor={currentColor || "BLUE"}
                  colorLabel={currentColorState?.label || currentColor || "현재 색"}
                  currentTurnLabel={currentTurnLabel}
                  canPass={canPass}
                  myTurn={myTurn}
                  currentScoreDetail={currentBlokusScoreDetail}
                  totalLegalPlacementCount={totalLegalPlacementCount}
                />
              </div>
            )}
          </div>
          <button
            type="button"
            className="mt-3 inline-flex w-full items-center justify-center gap-2 rounded-xl bg-slate-100 px-3 py-3 text-sm font-black text-slate-700 disabled:opacity-40"
            onClick={() => pass().catch(() => notifyError("아직 둘 수 있는 조각이 있습니다."))}
            disabled={!canPass}
          >
            <Ban className="h-4 w-4" />
            {canPass ? "둘 수 없음 · 패스" : "패스 불가"}
          </button>
          <div className="mt-2 rounded-xl bg-slate-50 px-3 py-2 text-[11px] font-bold leading-relaxed text-slate-500">
            {canPass
              ? "남은 모든 조각이 막혔습니다. 서버 규칙상 패스가 승인됩니다."
              : "패스는 남은 모든 조각이 막혔을 때만 가능합니다. 선택 조각이 막혔다면 다른 조각도 확인하세요."}
          </div>
        </div>

        <div className="rounded-[1.5rem] border border-slate-200 bg-white p-4 shadow-lg">
          <div className="mb-3 flex flex-col gap-1 sm:flex-row sm:items-center sm:justify-between">
            <div className="text-sm font-black text-slate-900">점수</div>
            <div className="text-[11px] font-bold text-slate-500">남은 칸은 감점 · 완주 +15 · 마지막 1칸 +5</div>
          </div>
          <div className="space-y-2">
            {scores.map((score) => {
              const scoreColors = get(score, "colors", "colors", []);
              return (
                <div key={get(score, "score_key", "scoreKey", score.label)} className="flex items-start justify-between gap-3 rounded-xl bg-slate-50 px-3 py-2">
                  <div className="min-w-0 flex-1">
                    <div className="truncate text-xs font-black text-slate-700">{scoreDisplayLabel(score)}</div>
                    <div className="mt-2 space-y-1">
                      {scoreColors.map((color) => {
                        const detail = blokusScoreDetailsByColor.get(color);
                        return (
                          <div key={color} className="flex flex-wrap items-center gap-1.5 text-[10px] font-bold text-slate-500">
                            <span className={`h-2.5 w-2.5 rounded-full ${colorClasses[color] || "bg-slate-300"}`} />
                            <span className={`${colorText[color] || "text-slate-600"} font-black`}>{blokusColorLabels[color] || color}</span>
                            {detail?.shared && <span className="rounded-full bg-sky-50 px-1.5 py-0.5 text-sky-700">공유 색</span>}
                            {detail?.completed ? (
                              <>
                                <span className="rounded-full bg-emerald-50 px-1.5 py-0.5 text-emerald-700">완주 +15</span>
                                {detail.monominoBonus > 0 && <span className="rounded-full bg-amber-50 px-1.5 py-0.5 text-amber-700">마지막 1칸 +5</span>}
                              </>
                            ) : (
                              <span>남은 {detail?.remainingSquares ?? 0}칸</span>
                            )}
                            <span className="text-slate-400">점수 {detail?.score ?? 0}</span>
                          </div>
                        );
                      })}
                    </div>
                  </div>
                  <div className="flex shrink-0 items-center gap-1 text-sm font-black text-slate-900">
                    {score.winner && <Crown className="h-4 w-4 text-amber-500" />}
                    {score.score}
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        <div className="rounded-[1.5rem] border border-slate-200 bg-white p-4 shadow-lg">
          <div className="mb-3 text-sm font-black text-slate-900">최근 수</div>
          <div className="space-y-2">
            {moveHistory.slice(-5).reverse().map((move) => (
              <div key={get(move, "turn_number", "turnNumber", 0)} className="rounded-xl bg-slate-50 px-3 py-2 text-xs font-bold text-slate-500">
                {get(move, "turn_number", "turnNumber", 0)}수 · {move.pass ? "패스" : get(move, "piece_code", "pieceCode", "")} · {move.color}
              </div>
            ))}
            {!moveHistory.length && (
              <TabletopHistoryEmptyState
                game="blokus"
                title="아직 배치 기록이 없습니다"
                detail="첫 조각을 놓거나 패스가 처리되면 색상, 조각, 순서가 이 기록 영역에 쌓입니다."
                nextAction="첫 배치"
              />
            )}
          </div>
        </div>
      </aside>
    </div>
  );
};

const maheTurtleSvgPalettes = [
  { shell: "#34d399", shellStroke: "#047857", body: "#bef264", bodyStroke: "#65a30d", text: "#064e3b" },
  { shell: "#38bdf8", shellStroke: "#0369a1", body: "#a5f3fc", bodyStroke: "#0891b2", text: "#0c4a6e" },
  { shell: "#fcd34d", shellStroke: "#b45309", body: "#fde68a", bodyStroke: "#d97706", text: "#78350f" },
  { shell: "#fb7185", shellStroke: "#be123c", body: "#fbcfe8", bodyStroke: "#db2777", text: "#881337" },
  { shell: "#a78bfa", shellStroke: "#6d28d9", body: "#f0abfc", bodyStroke: "#c026d3", text: "#4c1d95" },
  { shell: "#2dd4bf", shellStroke: "#0f766e", body: "#a7f3d0", bodyStroke: "#059669", text: "#134e4a" },
  { shell: "#fdba74", shellStroke: "#c2410c", body: "#fde68a", bodyStroke: "#d97706", text: "#7c2d12" },
  { shell: "#cbd5e1", shellStroke: "#475569", body: "#e2e8f0", bodyStroke: "#64748b", text: "#0f172a" },
];

const MaheTurtleArt = ({ seatNo, compact = false, className = "" }) => {
  const svgPalette = maheTurtleSvgPalettes[(Number(seatNo) - 1) % maheTurtleSvgPalettes.length] || maheTurtleSvgPalettes[0];
  const label = `${seatNo}번 거북이`;
  return (
    <svg
      viewBox="0 0 96 72"
      className={`${compact ? "h-6 w-8" : "h-8 w-11"} shrink-0 ${className}`}
      title={label}
      aria-label={label}
      role="img"
      data-smoke="mahe-turtle-token"
    >
      <g data-smoke="mahe-turtle-art">
        <ellipse cx="70" cy="38" rx="13" ry="11" fill={svgPalette.body} stroke={svgPalette.bodyStroke} strokeWidth="4" />
        <path d="M20 36l-11 8 11 8z" fill={svgPalette.body} stroke={svgPalette.bodyStroke} strokeWidth="4" strokeLinejoin="round" />
        <ellipse cx="33" cy="18" rx="10" ry="7" fill={svgPalette.body} stroke={svgPalette.bodyStroke} strokeWidth="4" transform="rotate(-18 33 18)" />
        <ellipse cx="33" cy="56" rx="10" ry="7" fill={svgPalette.body} stroke={svgPalette.bodyStroke} strokeWidth="4" transform="rotate(18 33 56)" />
        <ellipse cx="46" cy="38" rx="28" ry="22" fill={svgPalette.shell} stroke={svgPalette.shellStroke} strokeWidth="5" />
        <path d="M27 37c10-11 29-13 42-1" fill="none" stroke="rgba(255,255,255,0.58)" strokeWidth="4" strokeLinecap="round" />
        <path d="M46 17v42M24 38h52" stroke={svgPalette.shellStroke} strokeWidth="2.5" strokeLinecap="round" opacity="0.45" />
        <circle cx="76" cy="34" r="2.8" fill="#0f172a" />
        <text x="46" y="45" textAnchor="middle" fontSize="22" fontWeight="900" fill={svgPalette.text}>{seatNo}</text>
      </g>
    </svg>
  );
};

const TurtleStack = ({ seatNos = [], compact = false }) => (
  <div className={`flex items-center ${compact ? "-space-x-2" : "-space-x-1.5"}`}>
    {seatNos.map((seatNo, index) => (
      <MaheTurtleArt key={`${seatNo}-${index}`} seatNo={seatNo} compact={compact} />
    ))}
  </div>
);

const maheActionRouteTone = {
  ready: { fill: "#f8fafc", stroke: "#64748b", text: "#334155", soft: "#e2e8f0" },
  safe: { fill: "#ecfdf5", stroke: "#059669", text: "#047857", soft: "#bbf7d0" },
  caution: { fill: "#fffbeb", stroke: "#f59e0b", text: "#b45309", soft: "#fde68a" },
  danger: { fill: "#fff1f2", stroke: "#e11d48", text: "#be123c", soft: "#fecdd3" },
  bust: { fill: "#ffe4e6", stroke: "#be123c", text: "#9f1239", soft: "#fecdd3" },
};

const buildMaheActionRouteItems = ({
  phase,
  canRoll,
  canChoose,
  diceCount = 0,
  diceSum = 0,
  diceRollsLeft = 0,
  safeRemaining = 0,
  nextBustRolls = [],
  stopSteps = 0,
  stopScores = false,
  projectedSteps = 0,
  projectedDestination = 0,
  scoreRecipientText = "",
  bustReturnText = "",
  finalEggText = "",
  currentEgg = null,
  riskLevel = "ready",
}) => {
  const isFinished = phase === "FINISHED";
  const isChoosing = phase === "CHOOSE_DICE_COUNT";
  const actionValue = isFinished
    ? "결과 확인"
    : canChoose
      ? "주사위 개수 선택"
      : canRoll
        ? diceCount > 0
          ? "굴릴지 멈출지 선택"
          : "첫 주사위 굴림"
        : "차례 대기";
  const actionDetail = isFinished
    ? "알 카드 정산과 최종 점수를 확인합니다."
    : isChoosing
      ? "업힌 거북이의 맨 위 플레이어가 이번 굴림 개수를 정합니다."
      : canRoll
        ? "현재 합계, 남은 굴림 수, 보상 가능성을 함께 보고 판단합니다."
        : "현재 차례 플레이어의 선택이 끝나면 루트가 갱신됩니다.";
  const stopValue = stopSteps > 0
    ? `${stopSteps}칸 이동`
    : diceCount > 0
      ? "이동 없음"
      : "첫 굴림 전";
  const stopDetail = stopSteps > 0
    ? stopScores
      ? `${currentEgg ?? "-"}점 알 획득 후보입니다. ${scoreRecipientText}`
      : `멈추면 ${projectedDestination || "출발점"}번 칸 흐름으로 이동합니다.`
    : diceCount > 0
      ? "합계가 초과되어 서버 정산을 기다립니다."
      : "첫 굴림 뒤 멈춤 루트가 열립니다.";
  const riskValue = diceCount <= 0
    ? "초과 없음"
    : diceRollsLeft <= 0
      ? "자동 이동"
      : `${nextBustRolls.length}/6 초과`;
  const riskDetail = diceCount <= 0
    ? "첫 주사위는 실패 위험 없이 차례를 시작합니다."
    : diceRollsLeft <= 0
      ? "세 번째 주사위까지 안전하면 현재 합계로 이동합니다."
      : nextBustRolls.length
        ? `초과 눈 ${nextBustRolls.join(", ")} · 안전 여유 ${Math.max(0, safeRemaining)}`
        : "다음 굴림도 모두 안전한 상태입니다.";
  const outcomeValue = stopScores
    ? "보상 가능"
    : projectedSteps > 0
      ? `${projectedSteps}칸 후보`
      : isFinished
        ? "정산 완료"
        : "위험 확인";
  const outcomeDetail = finalEggText
    || (stopScores ? scoreRecipientText : bustReturnText)
    || "결승선을 넘는 거북이 스택의 맨 위 플레이어가 알을 받습니다.";

  return [
    {
      key: "action",
      label: "이번 선택",
      value: actionValue,
      detail: actionDetail,
      tone: canRoll || canChoose ? "border-emerald-100 bg-emerald-50 text-emerald-800" : "border-slate-100 bg-slate-50 text-slate-700",
    },
    {
      key: "stop",
      label: "멈춤 루트",
      value: stopValue,
      detail: stopDetail,
      tone: stopScores ? "border-amber-100 bg-amber-50 text-amber-800" : "border-slate-100 bg-white text-slate-700",
    },
    {
      key: "risk",
      label: "굴림 위험",
      value: riskValue,
      detail: riskDetail,
      tone: riskLevel === "danger" || riskLevel === "bust" ? "border-rose-100 bg-rose-50 text-rose-800" : "border-cyan-100 bg-cyan-50 text-cyan-800",
    },
    {
      key: "outcome",
      label: "보상 판단",
      value: outcomeValue,
      detail: outcomeDetail,
      tone: stopScores ? "border-amber-100 bg-amber-50 text-amber-800" : "border-violet-100 bg-violet-50 text-violet-800",
    },
  ];
};

const MaheActionRouteArt = ({
  phase,
  canRoll,
  canChoose,
  diceCount = 0,
  diceSum = 0,
  diceRollsLeft = 0,
  nextBustRolls = [],
  stopSteps = 0,
  stopScores = false,
  riskLevel = "ready",
}) => {
  const tone = maheActionRouteTone[riskLevel] || maheActionRouteTone.ready;
  const stateLabel = phase === "FINISHED"
    ? "결과"
    : canChoose
      ? "개수"
      : canRoll
        ? diceCount > 0
          ? "선택"
          : "시작"
        : "대기";
  const riskText = diceCount <= 0
    ? "안전"
    : diceRollsLeft <= 0
      ? "이동"
      : `${nextBustRolls.length}/6`;
  const nodes = [
    { key: "turn", label: "차례", value: stateLabel, x: 54, y: 72, fill: canRoll || canChoose ? "#ecfdf5" : "#f8fafc", stroke: canRoll || canChoose ? "#059669" : "#94a3b8", text: canRoll || canChoose ? "#047857" : "#475569" },
    { key: "dice", label: "합계", value: String(diceSum || 0), x: 142, y: 72, fill: tone.fill, stroke: tone.stroke, text: tone.text },
    { key: "risk", label: "위험", value: riskText, x: 230, y: 72, fill: diceCount > 0 && nextBustRolls.length >= 4 ? "#fff1f2" : "#ecfeff", stroke: diceCount > 0 && nextBustRolls.length >= 4 ? "#e11d48" : "#0891b2", text: diceCount > 0 && nextBustRolls.length >= 4 ? "#be123c" : "#0e7490" },
    { key: "stop", label: "멈춤", value: stopSteps > 0 ? `${stopSteps}` : "-", x: 318, y: 72, fill: stopScores ? "#fffbeb" : "#ffffff", stroke: stopScores ? "#f59e0b" : "#cbd5e1", text: stopScores ? "#b45309" : "#475569" },
  ];

  return (
    <svg
      viewBox="0 0 372 144"
      className="h-full min-h-[118px] w-full"
      role="img"
      aria-label={`마헤 선택 루트, 현재 합계 ${diceSum || 0}, 멈춤 이동 ${stopSteps || 0}칸`}
      data-smoke="mahe-action-route-art"
    >
      <rect x="10" y="10" width="352" height="124" rx="24" fill="#f8fafc" stroke="#e2e8f0" strokeWidth="3" />
      <path d="M54 72h264" stroke={tone.soft} strokeWidth="12" strokeLinecap="round" />
      <path d="M54 72h264" stroke={tone.stroke} strokeWidth="4" strokeLinecap="round" opacity="0.72" />
      {nodes.map((node) => (
        <g key={node.key} data-smoke="mahe-action-route-node" data-route-key={node.key}>
          <circle cx={node.x} cy={node.y} r="30" fill="#ffffff" stroke={node.stroke} strokeWidth="4" />
          <circle cx={node.x} cy={node.y} r="21" fill={node.fill} stroke="#ffffff" strokeWidth="3" />
          <text x={node.x} y={node.y - 5} textAnchor="middle" fontSize="9" fontWeight="900" fill={node.text}>{node.label}</text>
          <text x={node.x} y={node.y + 13} textAnchor="middle" fontSize="16" fontWeight="900" fill={node.text}>{node.value}</text>
        </g>
      ))}
      <rect x="38" y="112" width="284" height="18" rx="9" fill="#ffffff" stroke="#e2e8f0" />
      <text x="180" y="125" textAnchor="middle" fontSize="10" fontWeight="900" fill="#475569">
        굴림 · 멈춤 · 보상 판단
      </text>
      {stopScores && (
        <g>
          <circle cx="338" cy="36" r="16" fill="#fef3c7" stroke="#f59e0b" strokeWidth="3" />
          <text x="338" y="41" textAnchor="middle" fontSize="12" fontWeight="900" fill="#b45309">알</text>
        </g>
      )}
    </svg>
  );
};

const MaheActionRoutePanel = ({
  phase,
  canRoll,
  canChoose,
  dice = [],
  diceSum = 0,
  diceRollsLeft = 0,
  safeRemaining = 0,
  nextBustRolls = [],
  stopSteps = 0,
  stopScores = false,
  projectedSteps = 0,
  projectedDestination = 0,
  scoreRecipientText = "",
  bustReturnText = "",
  finalEggText = "",
  currentEgg = null,
  riskLevel = "ready",
}) => {
  const diceCount = dice.length || 0;
  const items = buildMaheActionRouteItems({
    phase,
    canRoll,
    canChoose,
    diceCount,
    diceSum,
    diceRollsLeft,
    safeRemaining,
    nextBustRolls,
    stopSteps,
    stopScores,
    projectedSteps,
    projectedDestination,
    scoreRecipientText,
    bustReturnText,
    finalEggText,
    currentEgg,
    riskLevel,
  });

  return (
    <section
      data-smoke="mahe-action-route-panel"
      data-phase={phase || ""}
      data-can-roll={canRoll ? "true" : "false"}
      data-can-choose={canChoose ? "true" : "false"}
      data-dice-count={diceCount}
      data-stop-steps={stopSteps}
      className="mb-4 overflow-hidden rounded-2xl border border-teal-100 bg-gradient-to-br from-white via-teal-50 to-amber-50 p-3 shadow-sm sm:rounded-[1.5rem] sm:p-4"
    >
      <div className="grid gap-3 lg:grid-cols-[minmax(220px,0.82fr)_minmax(0,1fr)] lg:items-center">
        <div className="min-h-[128px]">
          <MaheActionRouteArt
            phase={phase}
            canRoll={canRoll}
            canChoose={canChoose}
            diceCount={diceCount}
            diceSum={diceSum}
            diceRollsLeft={diceRollsLeft}
            nextBustRolls={nextBustRolls}
            stopSteps={stopSteps}
            stopScores={stopScores}
            riskLevel={riskLevel}
          />
        </div>
        <div className="min-w-0">
          <div className="flex flex-wrap items-start justify-between gap-2">
            <div>
              <div className="text-[11px] font-black text-teal-700">마헤 선택 루트</div>
              <h3 className="text-base font-black text-slate-900">굴림, 멈춤, 보상 판단</h3>
            </div>
            <div className="rounded-full border border-teal-100 bg-white px-3 py-1 text-[11px] font-black text-teal-700">
              합계 {diceSum || 0} · 주사위 {diceCount}/3
            </div>
          </div>
          <div className="mt-3 grid gap-2 sm:grid-cols-2">
            {items.map((item) => (
              <div key={item.key} data-smoke="mahe-action-route-item" data-route-key={item.key} className={`min-h-[102px] rounded-xl border px-3 py-2.5 ${item.tone}`}>
                <div className="text-[10px] font-black opacity-70">{item.label}</div>
                <div className="mt-0.5 text-sm font-black leading-snug">{item.value}</div>
                <div className="mt-1 text-[11px] font-bold leading-relaxed opacity-80">{item.detail}</div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
};

const MaheBoard = ({ gameState, players: roomPlayers = [], mySeatNo, onAction }) => {
  const trackSize = Number(get(gameState, "track_size", "trackSize", 21));
  const variantName = get(gameState, "variant_name", "variantName", "본게임");
  const phase = gameState?.phase || "ROLLING";
  const activeSeatNo = Number(get(gameState, "active_seat_no", "activeSeatNo", 0));
  const decisionSeatNo = Number(get(gameState, "decision_seat_no", "decisionSeatNo", 0));
  const currentEgg = get(gameState, "current_egg", "currentEgg", null);
  const dice = get(gameState, "dice", "dice", []);
  const diceSum = Number(get(gameState, "dice_sum", "diceSum", 0));
  const turtles = get(gameState, "turtles", "turtles", []);
  const stacks = get(gameState, "stacks", "stacks", []);
  const scores = get(gameState, "scores", "scores", []);
  const eggDeck = get(gameState, "egg_deck", "eggDeck", []);
  const finalEggRound = Boolean(get(gameState, "final_egg_round", "finalEggRound", false));
  const moveHistory = get(gameState, "move_history", "moveHistory", []);
  const activeTurtle = turtles.find((turtle) => Number(get(turtle, "seat_no", "seatNo", 0)) === activeSeatNo);
  const activePosition = Number(activeTurtle?.position || 0);
  const projectedDiceCount = dice.length || 1;
  const projectedSteps = diceSum > 0 && diceSum <= 7 ? diceSum * projectedDiceCount : 0;
  const projectedDestination = projectedSteps ? (activePosition + projectedSteps) % trackSize : activePosition;
  const projectedScores = projectedSteps ? activePosition + projectedSteps >= trackSize : false;
  const safeRemaining = Math.max(0, 7 - diceSum);
  const diceRollsLeft = Math.max(0, 3 - dice.length);
  const nextSafeRolls = dice.length > 0 && diceRollsLeft > 0
    ? [1, 2, 3, 4, 5, 6].filter((value) => value <= safeRemaining)
    : [];
  const nextBustRolls = dice.length > 0 && diceRollsLeft > 0
    ? [1, 2, 3, 4, 5, 6].filter((value) => value > safeRemaining)
    : [];
  const stopSteps = diceSum > 0 && diceSum <= 7 ? diceSum * dice.length : 0;
  const stopScores = stopSteps > 0 && activePosition + stopSteps >= trackSize;
  const riskLevel = diceSum > 7
    ? "bust"
    : dice.length === 0
      ? "ready"
      : safeRemaining <= 1
        ? "danger"
        : safeRemaining <= 3
          ? "caution"
          : "safe";
  const riskLabel = diceSum > 7
    ? "합계 초과"
    : dice.length === 0
      ? "첫 주사위는 안전"
      : diceRollsLeft === 0
        ? "세 번째 주사위 자동 이동"
        : `다음 주사위 위험 ${nextBustRolls.length}/6`;
  const startSeatNos = turtles
    .filter((turtle) => Number(turtle.position) === 0)
    .map((turtle) => Number(get(turtle, "seat_no", "seatNo", 0)))
    .filter(Boolean);
  const stackByPosition = useMemo(() => {
    const next = new Map();
    stacks.forEach((stack) => next.set(Number(stack.position), get(stack, "seat_nos", "seatNos", [])));
    return next;
  }, [stacks]);
  const activeStackSeatNos = stackByPosition.get(activePosition) || (activeSeatNo ? [activeSeatNo] : []);
  const activeStackIndex = activeStackSeatNos.indexOf(activeSeatNo);
  const activeMovingSeatNos = activeStackIndex >= 0 ? activeStackSeatNos.slice(activeStackIndex) : (activeSeatNo ? [activeSeatNo] : []);
  const activeStackTopSeatNo = activeStackSeatNos.length ? activeStackSeatNos[activeStackSeatNos.length - 1] : activeSeatNo;
  const projectedScorerSeatNo = activeMovingSeatNos.length ? activeMovingSeatNos[activeMovingSeatNos.length - 1] : activeSeatNo;
  const activeIsCarried = activeStackTopSeatNo && activeStackTopSeatNo !== activeSeatNo;
  const canRoll = phase === "ROLLING" && activeSeatNo === mySeatNo;
  const canChoose = phase === "CHOOSE_DICE_COUNT" && decisionSeatNo === mySeatNo;
  const winners = scores.filter((score) => Boolean(get(score, "winner", "winner", false)));
  const playerName = (seatNo) => roomPlayers.find((player) => seatNoOf(player) === Number(seatNo))?.nickname || `${seatNo}번`;
  const scoreBySeatNo = new Map(scores.map((score) => [Number(get(score, "seat_no", "seatNo", 0)), score]));
  const maheRewardPressureRows = (turtles.length ? turtles : scores.map((score) => ({
    seatNo: get(score, "seat_no", "seatNo", 0),
    seat_no: get(score, "seat_no", "seatNo", 0),
    position: 0,
  })))
    .map((turtle) => {
      const seatNo = Number(get(turtle, "seat_no", "seatNo", 0));
      const position = Number(get(turtle, "position", "position", 0)) || 0;
      const stackSeatNos = (stackByPosition.get(position) || [seatNo]).map(Number).filter(Boolean);
      const stackIndex = stackSeatNos.indexOf(seatNo);
      const score = scoreBySeatNo.get(seatNo) || {};
      const cards = listOf(get(score, "cards", "cards", []));
      return {
        seatNo,
        name: playerName(seatNo),
        position,
        score: Number(get(score, "score", "score", 0)) || 0,
        cardsCount: cards.length,
        stackDepth: stackSeatNos.length,
        stackIndex: stackIndex >= 0 ? stackIndex : 0,
        topSeatNo: stackSeatNos.length ? stackSeatNos[stackSeatNos.length - 1] : seatNo,
        isLeader: false,
      };
    })
    .filter((row) => row.seatNo);
  const maheRewardLeaderScore = Math.max(0, ...maheRewardPressureRows.map((row) => Number(row.score || 0)));
  maheRewardPressureRows.forEach((row) => {
    row.isLeader = Number(row.score || 0) === maheRewardLeaderScore && maheRewardLeaderScore > 0;
  });
  const activeStackOrderText = activeStackSeatNos.length
    ? activeStackSeatNos.map((seatNo) => playerName(seatNo)).join(" → ")
    : "-";
  const activeMovingText = activeMovingSeatNos.length
    ? activeMovingSeatNos.map((seatNo) => playerName(seatNo)).join(", ")
    : "-";
  const carriedChoiceText = activeIsCarried
    ? `${playerName(activeStackTopSeatNo)}님이 맨 위에 있어 ${playerName(activeSeatNo)}님의 주사위 개수를 정합니다.`
    : `${playerName(activeSeatNo)}님이 직접 주사위를 굴립니다.`;
  const winnerText = winners.map((score) => playerName(get(score, "seat_no", "seatNo", 0))).join(", ");
  const winningScore = winners.length ? Number(get(winners[0], "score", "score", 0)) : 0;
  const turnMessage = phase === "FINISHED"
    ? "모든 알 카드가 정산되었습니다."
    : phase === "CHOOSE_DICE_COUNT"
      ? carriedChoiceText
      : `${playerName(activeSeatNo)}님이 주사위를 굴립니다.`;
  const bustReturnText = activeMovingSeatNos.length > 1
    ? `합계가 8 이상이면 ${activeMovingText} 모두 출발점으로 돌아갑니다.`
    : "합계가 8 이상이면 현재 거북이가 출발점으로 돌아갑니다.";
  const scoreRecipientText = projectedScorerSeatNo
    ? `결승선을 넘으면 맨 위 ${playerName(projectedScorerSeatNo)}님이 알을 받습니다.`
    : "결승선을 넘으면 맨 위 거북이가 알을 받습니다.";
  const finalEggText = finalEggRound
    ? "이 7점 알을 누군가 획득하면 게임이 끝납니다."
    : eggDeck.length === 0
      ? "현재 알이 사라지면 마지막 7점 알이 공개됩니다."
      : "";
  const mahePhaseLabel = phase === "FINISHED" ? "게임 종료"
    : phase === "CHOOSE_DICE_COUNT" ? "주사위 개수 선택"
      : "주사위 굴리기";
  const maheTurnGuidance = (() => {
    if (phase === "FINISHED") {
      return winnerText ? `${winnerText} 승리, 총 ${winningScore}점입니다.` : "모든 알 카드가 정산되었습니다.";
    }
    if (phase === "CHOOSE_DICE_COUNT") {
      return canChoose ? "업힌 거북이의 맨 위 플레이어로서 주사위 개수를 선택하세요." : `${playerName(decisionSeatNo)}님의 주사위 개수 선택을 기다리는 중입니다.`;
    }
    if (!canRoll) {
      return `${playerName(activeSeatNo)}님의 주사위 선택을 기다리는 중입니다.`;
    }
    if (!dice.length) {
      return "주사위 1개부터 굴립니다. 이후 더 굴릴지 멈출지 선택하세요.";
    }
    if (diceSum > 7) {
      return `${bustReturnText} 서버가 이동 실패를 정리합니다.`;
    }
    return `지금 멈추면 ${stopSteps}칸 이동합니다. 더 굴리면 ${riskLabel.toLowerCase()}입니다.`;
  })();
  const maheQuickFacts = [
    { label: "단계", value: mahePhaseLabel },
    { label: "차례", value: phase === "FINISHED" ? "종료" : canRoll || canChoose ? "내 차례" : playerName(activeSeatNo || decisionSeatNo) },
    { label: "합계", value: String(diceSum || 0) },
    { label: "알", value: `${currentEgg ?? "-"}점` },
  ];
  const maheRewardLeader = maheRewardPressureRows.slice().sort((left, right) => (
    Number(right.score || 0) - Number(left.score || 0)
    || Number(right.cardsCount || 0) - Number(left.cardsCount || 0)
    || Number(right.position || 0) - Number(left.position || 0)
  ))[0] || null;
  const maheClosestToGoal = maheRewardPressureRows.slice().sort((left, right) => Number(right.position || 0) - Number(left.position || 0))[0] || null;
  const maheBottomSummaryItems = [
    {
      key: "turn",
      label: "차례",
      value: mahePhaseLabel,
      detail: turnMessage,
      tone: phase === "FINISHED" ? "border-amber-100 bg-amber-50 text-amber-800" : canRoll || canChoose ? "border-emerald-100 bg-emerald-50 text-emerald-800" : "border-slate-100 bg-slate-50 text-slate-700",
    },
    {
      key: "risk",
      label: "위험",
      value: riskLabel,
      detail: diceSum > 7 ? bustReturnText : `멈추면 ${stopSteps || 0}칸 · 실패 눈 ${nextBustRolls.length}/6`,
      tone: riskLevel === "bust" || riskLevel === "danger" ? "border-rose-100 bg-rose-50 text-rose-800" : riskLevel === "caution" ? "border-amber-100 bg-amber-50 text-amber-800" : "border-cyan-100 bg-cyan-50 text-cyan-800",
    },
    {
      key: "egg",
      label: "알",
      value: `${currentEgg ?? "-"}점`,
      detail: `${eggDeck.length}장 남음${stopScores || projectedScores ? ` · ${scoreRecipientText}` : ""}${finalEggText ? ` · ${finalEggText}` : ""}`,
      tone: stopScores || projectedScores || finalEggRound ? "border-amber-100 bg-amber-50 text-amber-800" : "border-slate-100 bg-white text-slate-700",
    },
    {
      key: "leader",
      label: "선두",
      value: maheRewardLeader ? `${maheRewardLeader.name} ${maheRewardLeader.score}점` : "대기",
      detail: maheClosestToGoal ? `결승선에 가까운 말: ${maheClosestToGoal.name} · ${maheClosestToGoal.position}/${trackSize}` : "점수판이 도착하면 선두와 결승선 거리가 표시됩니다.",
      tone: "border-emerald-100 bg-emerald-50 text-emerald-800",
    },
  ];
  const startActive = activePosition === 0;
  const startProjected = Boolean(projectedSteps) && projectedDestination === 0;
  const startSpaceLabel = startSeatNos.length
    ? [
        `출발점 · 아래에서 위 순서 ${startSeatNos.map((seatNo) => playerName(seatNo)).join(" → ")}`,
        startActive ? "현재 차례 거북이 위치" : "",
        startProjected ? `${projectedSteps}칸 이동 시 도착 예정` : "",
        startProjected && projectedScores ? "알 획득 가능" : "",
      ].filter(Boolean).join(" · ")
    : [
        "출발점 · 비어 있음",
        startActive ? "현재 차례 거북이 위치" : "",
        startProjected ? `${projectedSteps}칸 이동 시 도착 예정` : "",
      ].filter(Boolean).join(" · ");
  const diceChoiceSummaries = useMemo(
    () => [1, 2, 3].map((count) => summarizeMaheDiceChoice(count, activePosition, trackSize)),
    [activePosition, trackSize],
  );
  const choiceSummaryByCount = useMemo(
    () => new Map(diceChoiceSummaries.map((summary) => [summary.diceCount, summary])),
    [diceChoiceSummaries],
  );
  const nextRollOutcomes = useMemo(() => {
    if (phase !== "ROLLING" || !dice.length || diceRollsLeft <= 0 || diceSum > 7) {
      return [];
    }
    const nextDiceCount = dice.length + 1;
    return [1, 2, 3, 4, 5, 6].map((face) => {
      const nextSum = diceSum + face;
      const bust = nextSum > 7;
      const steps = bust ? 0 : nextSum * nextDiceCount;
      return {
        face,
        bust,
        steps,
        sum: nextSum,
        scores: steps > 0 && activePosition + steps >= trackSize,
      };
    });
  }, [activePosition, dice.length, diceRollsLeft, diceSum, phase, trackSize]);

  const roll = async () => onAction({ action_type: "ROLL_DIE" });
  const stop = async () => onAction({ action_type: "STOP_ROLLING" });
  const choose = async (diceCount) => onAction({ action_type: "CHOOSE_DICE_COUNT", dice_count: diceCount });
  const renderDiceChoiceButton = (count) => {
    const summary = choiceSummaryByCount.get(count) || summarizeMaheDiceChoice(count, activePosition, trackSize);
    const tone = summary.bustPercent >= 70
      ? "bg-rose-600 hover:bg-rose-700"
      : summary.bustPercent > 0
        ? "bg-amber-500 hover:bg-amber-600"
        : "bg-emerald-600 hover:bg-emerald-700";
    const choiceLabel = [
      `${count}개 선택`,
      `안전 ${summary.safePercent}%`,
      `실패 ${summary.bustPercent}%`,
      `성공 ${summary.minSafeSteps}-${summary.maxSafeSteps}칸`,
      summary.scorePercent > 0 ? `득점 가능 ${summary.scorePercent}%` : `성공 평균 ${summary.expectedSafeSteps}칸`,
      canChoose ? "선택 가능" : "선택 대기",
    ].join(" · ");
    return (
      <button
        key={count}
        type="button"
        className={`min-h-[74px] rounded-xl px-3 py-2.5 text-left text-white shadow-sm transition disabled:opacity-40 ${tone}`}
        disabled={!canChoose}
        onClick={() => choose(count).catch(() => notifyError("주사위 개수 선택 실패"))}
        aria-label={choiceLabel}
        title={choiceLabel}
      >
        <div className="flex items-center justify-between gap-2">
          <span className="text-sm font-black">{count}개</span>
          <span className="rounded-full bg-white/20 px-1.5 py-0.5 text-[10px] font-black">안전 {summary.safePercent}%</span>
        </div>
        <div className="mt-1 text-[10px] font-bold leading-relaxed text-white/85">
          실패 {summary.bustPercent}% · 성공 {summary.minSafeSteps}-{summary.maxSafeSteps}칸
        </div>
        <div className="text-[10px] font-bold leading-relaxed text-white/85">
          {summary.scorePercent > 0 ? `득점 가능 ${summary.scorePercent}%` : `성공 평균 ${summary.expectedSafeSteps}칸`}
        </div>
      </button>
    );
  };
  const renderNextRollPreview = () => {
    if (!nextRollOutcomes.length) {
      return null;
    }
    const nextDiceCount = dice.length + 1;
    return (
      <div className="mt-2 rounded-xl border border-slate-200 bg-white px-3 py-2 shadow-sm">
        <div className="mb-1 flex flex-wrap items-center justify-between gap-1 text-[11px] font-black text-slate-700">
          <span>다음 주사위 결과</span>
          {nextDiceCount === 3 && <span className="text-amber-600">세 번째는 안전하면 즉시 이동</span>}
        </div>
        <div className="grid grid-cols-3 gap-1.5">
          {nextRollOutcomes.map((outcome) => {
            const outcomeLabel = [
              `다음 눈 ${outcome.face}`,
              `합계 ${outcome.sum}`,
              outcome.bust ? "실패" : `${outcome.steps}칸 이동`,
              outcome.scores ? "알 획득 가능" : "",
            ].filter(Boolean).join(" · ");
            return (
              <div
                key={outcome.face}
                className={`rounded-lg border px-2 py-1.5 text-[10px] font-black leading-tight ${
                  outcome.bust
                    ? "border-rose-100 bg-rose-50 text-rose-700"
                    : outcome.scores
                      ? "border-amber-100 bg-amber-50 text-amber-700"
                      : "border-emerald-100 bg-emerald-50 text-emerald-700"
                }`}
                role="img"
                aria-label={outcomeLabel}
                title={outcomeLabel}
              >
                <div className="flex items-center justify-between gap-1">
                  <span>{outcome.face}</span>
                  <span>합 {outcome.sum}</span>
                </div>
                <div className="mt-0.5 text-[9px] font-bold">
                  {outcome.bust ? "실패" : `${outcome.steps}칸`}
                  {outcome.scores ? " · 알 가능" : ""}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    );
  };

  return (
    <>
    <div className="grid gap-4 xl:grid-cols-[minmax(0,1fr)_360px]">
      <div id="mahe-board-panel" className="scroll-mt-24 rounded-[1.5rem] border border-slate-200 bg-white p-3 shadow-lg sm:p-4">
        <div className="mb-4 flex flex-wrap items-center justify-between gap-2">
          <div className="flex items-center gap-2 text-sm font-black text-slate-900">
            <Shield className="h-4 w-4 text-primary-600" />
            마헤 트랙
          </div>
          <div className="rounded-full border border-emerald-100 bg-emerald-50 px-3 py-1 text-xs font-black text-emerald-700">
            {phase === "FINISHED" ? "게임 종료" : `${playerName(activeSeatNo)} 차례`}
          </div>
          <div className="rounded-full border border-amber-100 bg-amber-50 px-3 py-1 text-xs font-black text-amber-700">
            {variantName}
          </div>
        </div>
        <div className="mb-3 rounded-2xl border border-emerald-100 bg-emerald-50 px-3 py-2.5" role="status" aria-live="polite" aria-atomic="true">
          <div className="flex flex-wrap items-center gap-2">
            <div className="rounded-xl bg-emerald-600 p-2 text-white shadow-sm">
              <Dices className="h-4 w-4" />
            </div>
            <div className="min-w-0 flex-1 text-sm font-black leading-relaxed text-slate-900">
              {maheTurnGuidance}
            </div>
            <div className="flex shrink-0 flex-wrap gap-1.5">
              {maheQuickFacts.slice(2).map((item) => (
                <span key={item.label} className="rounded-full bg-white/85 px-2.5 py-1 text-[11px] font-black text-slate-600">
                  {item.label} {item.value}
                </span>
              ))}
            </div>
          </div>
        </div>

        <div className="relative mx-auto aspect-square w-full max-w-[620px] rounded-full bg-gradient-to-br from-cyan-100 via-emerald-100 to-amber-100 p-2 shadow-inner sm:p-4">
          <div className="absolute inset-[24%] rounded-full bg-gradient-to-br from-amber-200 to-yellow-300 shadow-inner" />
          <div className="absolute left-1/2 top-1/2 flex h-20 w-20 -translate-x-1/2 -translate-y-1/2 flex-col items-center justify-center rounded-full border border-white/80 bg-white/90 text-center shadow-lg sm:h-24 sm:w-24 lg:h-28 lg:w-28">
            <div className="text-[11px] font-black text-slate-500">{finalEggRound ? "마지막 보상" : "현재 알"}</div>
            <div className="text-2xl font-black text-amber-600">{currentEgg ?? "-"}</div>
            <div className="mt-1 text-[10px] font-bold text-slate-400">남은 카드 {eggDeck.length}</div>
          </div>
          <div
            className={`absolute left-1/2 top-[62%] max-w-[72%] -translate-x-1/2 rounded-full border bg-white/90 px-2 py-1.5 shadow sm:top-[60%] sm:px-3 sm:py-2 ${startProjected ? "tabletop-projected-space border-amber-300 ring-2 ring-amber-200" : startActive ? "tabletop-active-space border-emerald-300 ring-2 ring-emerald-200" : "border-slate-200"}`}
            role="img"
            aria-label={startSpaceLabel}
            title={startSpaceLabel}
          >
            <TurtleStack seatNos={startSeatNos} compact={startSeatNos.length > 4} />
          </div>
          {Array.from({ length: trackSize - 1 }, (_, index) => {
            const position = index + 1;
            const angle = (index / (trackSize - 1)) * Math.PI * 2 - Math.PI / 2;
            const x = 50 + Math.cos(angle) * 43;
            const y = 50 + Math.sin(angle) * 43;
            const seatNos = stackByPosition.get(position) || [];
            const activePositionCell = position === activePosition;
            const projectedPositionCell = position === projectedDestination && projectedSteps;
            const spaceLabel = [
              `${position}번 칸`,
              seatNos.length ? `아래에서 위 순서 ${seatNos.map((seatNo) => playerName(seatNo)).join(" → ")}` : "비어 있음",
              activePositionCell ? "현재 차례 거북이 위치" : "",
              projectedPositionCell ? `${projectedSteps}칸 이동 시 도착 예정` : "",
              projectedPositionCell && projectedScores ? "알 획득 가능" : "",
            ].filter(Boolean).join(" · ");
            return (
              <div
                key={position}
                className={`absolute flex h-8 w-8 -translate-x-1/2 -translate-y-1/2 flex-col items-center justify-center rounded-full border bg-white/90 text-[10px] font-black shadow sm:h-10 sm:w-10 lg:h-12 lg:w-12 ${projectedPositionCell ? "tabletop-projected-space border-amber-300 text-amber-700 ring-2 ring-amber-200" : activePositionCell ? "tabletop-active-space border-emerald-300 text-emerald-700 ring-2 ring-emerald-200" : "border-white text-slate-400"}`}
                style={{ left: `${x}%`, top: `${y}%` }}
                role="img"
                aria-label={spaceLabel}
                title={spaceLabel}
              >
                <span>{position}</span>
                {!!seatNos.length && <TurtleStack seatNos={seatNos} compact />}
              </div>
            );
          })}
        </div>
        <div id="mahe-action-strip" className="tabletop-mobile-action-strip sticky z-20 mt-3 scroll-mt-24 rounded-2xl border border-slate-200 bg-white/95 p-3 shadow-xl backdrop-blur xl:hidden">
          <div className="flex flex-wrap items-center justify-between gap-2">
            <div className="text-xs font-black text-slate-900" role="status" aria-live="polite" aria-atomic="true">{turnMessage}</div>
            <div className={`rounded-full px-2 py-1 text-[11px] font-black ${diceSum > 7 ? "bg-rose-50 text-rose-700" : "bg-slate-100 text-slate-600"}`}>
              합계 {diceSum || 0}
            </div>
          </div>
          {activeStackSeatNos.length > 1 && (
            <div className="mt-2 rounded-xl border border-teal-100 bg-teal-50 px-3 py-2 text-[11px] font-bold leading-relaxed text-teal-700">
              아래→위 {activeStackOrderText} · 이번 이동 {activeMovingText}
              {activeIsCarried ? ` · 선택권 ${playerName(activeStackTopSeatNo)}` : ""}
              {projectedScores || stopScores ? ` · ${scoreRecipientText}` : ""}
            </div>
          )}
          <div className="mt-2 flex items-center justify-between gap-2">
            <div className="flex gap-1.5">
              {[0, 1, 2].map((index) => (
                <div key={index} className="flex h-9 w-9 items-center justify-center rounded-lg border border-slate-200 bg-slate-50 text-base font-black text-slate-800">
                  {dice[index] || "-"}
                </div>
              ))}
            </div>
            <div className={`min-w-0 flex-1 rounded-xl border px-2 py-1.5 text-[11px] font-bold leading-relaxed ${maheRiskToneClasses[riskLevel]}`}>
              {riskLabel}
              {stopSteps > 0 ? ` · 멈추면 ${stopSteps}칸` : ""}
            </div>
          </div>
          {renderNextRollPreview()}
          <div className="mt-2 rounded-xl bg-slate-50 px-3 py-2 text-[11px] font-bold leading-relaxed text-slate-500">
            {bustReturnText}
            {(projectedScores || stopScores) ? ` ${scoreRecipientText}` : ""}
            {finalEggText ? ` ${finalEggText}` : ""}
          </div>
          {phase === "CHOOSE_DICE_COUNT" ? (
            <div className="mt-2 grid grid-cols-3 gap-2">
              {[1, 2, 3].map(renderDiceChoiceButton)}
            </div>
          ) : (
            <div className="mt-2 grid grid-cols-2 gap-2">
              <button
                type="button"
                className="min-h-11 rounded-xl bg-slate-900 px-3 py-3 text-sm font-black text-white disabled:opacity-40"
                disabled={!canRoll || dice.length >= 3}
                onClick={() => roll().catch(() => notifyError("주사위 굴리기 실패"))}
              >
                굴리기
              </button>
              <button
                type="button"
                className="min-h-11 rounded-xl bg-amber-500 px-3 py-3 text-sm font-black text-white disabled:opacity-40"
                disabled={!canRoll || !dice.length}
                onClick={() => stop().catch(() => notifyError("이동 실패"))}
              >
                멈추기
              </button>
            </div>
          )}
        </div>
      </div>

      <aside className="space-y-4">
        <div data-smoke="mahe-side-dice-panel" className="hidden rounded-[1.5rem] border border-slate-200 bg-white p-3 shadow-lg sm:p-4 xl:block">
          <div className="text-sm font-black text-slate-900">주사위</div>
          <div className="mt-2 rounded-xl bg-slate-50 px-3 py-2 text-xs font-bold leading-relaxed text-slate-500" role="status" aria-live="polite" aria-atomic="true">
            {turnMessage}
          </div>
          {activeStackSeatNos.length > 1 && (
            <div className="mt-2 rounded-xl border border-teal-100 bg-teal-50 px-3 py-2 text-xs font-bold leading-relaxed text-teal-700">
              <div className="font-black">업고 가기</div>
              <div>아래→위 {activeStackOrderText}</div>
              <div>이번 이동 {activeMovingText}</div>
              {activeIsCarried && <div>맨 위 거북이 {playerName(activeStackTopSeatNo)}님이 주사위 개수를 정합니다.</div>}
              {(projectedScores || stopScores) && <div>{scoreRecipientText}</div>}
            </div>
          )}
          <div className="mt-3 flex gap-2">
            {[0, 1, 2].map((index) => (
              <div key={index} className="flex h-12 w-12 items-center justify-center rounded-xl border border-slate-200 bg-slate-50 text-xl font-black text-slate-800">
                {dice[index] || "-"}
              </div>
            ))}
          </div>
          <div className={`mt-3 rounded-xl px-3 py-2 text-sm font-black ${diceSum > 7 ? "bg-rose-50 text-rose-700" : "bg-slate-50 text-slate-600"}`}>
            합계 {diceSum}
          </div>
          <div className={`mt-2 rounded-xl border px-3 py-2 text-xs font-bold leading-relaxed ${maheRiskToneClasses[riskLevel]}`}>
            <div className="flex flex-wrap items-center justify-between gap-2">
              <span className="font-black">{riskLabel}</span>
              <span>안전 한도 {safeRemaining}</span>
            </div>
            {dice.length > 0 && diceRollsLeft > 0 && (
              <div className="mt-1">
                안전 눈 {nextSafeRolls.join(", ") || "없음"} · 실패 눈 {nextBustRolls.join(", ") || "없음"}
              </div>
            )}
            {stopSteps > 0 && (
              <div className="mt-1">
                지금 멈추면 {stopSteps}칸 이동{stopScores ? ` · ${playerName(projectedScorerSeatNo)}님 ${currentEgg ?? 0}점 알 획득 가능` : ""}
              </div>
            )}
            <div className="mt-1">{bustReturnText}</div>
          </div>
          {renderNextRollPreview()}
          {projectedSteps > 0 && (
            <div className="mt-2 rounded-xl bg-amber-50 px-3 py-2 text-xs font-bold text-amber-700">
              예상 이동 {projectedSteps}칸 · 도착 {projectedDestination || "출발점"}
              {projectedScores ? ` · ${playerName(projectedScorerSeatNo)}님 ${currentEgg ?? 0}점 획득 가능` : ""}
            </div>
          )}
          <div className="mt-2 grid grid-cols-2 gap-2 text-xs font-bold">
            <div className="rounded-xl bg-amber-50 px-3 py-2 text-amber-700">
              {finalEggRound ? "마지막 보상" : "공개 알"} {currentEgg ?? "-"}점
            </div>
            <div className="rounded-xl bg-emerald-50 px-3 py-2 text-emerald-700">
              남은 알 {eggDeck.length}장
            </div>
          </div>
          {finalEggText && (
            <div className="mt-2 rounded-xl border border-amber-100 bg-amber-50 px-3 py-2 text-xs font-bold leading-relaxed text-amber-800">
              {finalEggText}
            </div>
          )}
          {phase === "CHOOSE_DICE_COUNT" ? (
            <div className="mt-3 grid grid-cols-3 gap-2">
              {[1, 2, 3].map(renderDiceChoiceButton)}
            </div>
          ) : (
            <div className="mt-3 grid grid-cols-2 gap-2">
              <button
                type="button"
                className="min-h-11 rounded-xl bg-slate-900 px-3 py-3 text-sm font-black text-white disabled:opacity-40"
                disabled={!canRoll || dice.length >= 3}
                onClick={() => roll().catch(() => notifyError("주사위 굴리기 실패"))}
              >
                굴리기
              </button>
              <button
                type="button"
                className="min-h-11 rounded-xl bg-amber-500 px-3 py-3 text-sm font-black text-white disabled:opacity-40"
                disabled={!canRoll || !dice.length}
                onClick={() => stop().catch(() => notifyError("이동 실패"))}
              >
                멈추기
              </button>
            </div>
          )}
        </div>

        <div id="dalmuti-status-panel" className="scroll-mt-24 rounded-[1.5rem] border border-slate-200 bg-white p-4 shadow-lg">
          <div className="mb-3 flex flex-col gap-1 sm:flex-row sm:items-center sm:justify-between">
            <div className="text-sm font-black text-slate-900">점수</div>
            <div className="text-[11px] font-bold text-slate-500">동점이면 알 카드를 더 많이 모은 플레이어가 앞섭니다.</div>
          </div>
          {phase === "FINISHED" && winners.length > 0 && (
            <div className="mb-3 flex flex-wrap items-center justify-between gap-2 rounded-xl border border-amber-200 bg-amber-50 px-3 py-2">
              <div className="flex items-center gap-2 text-sm font-black text-amber-900">
                <Crown className="h-4 w-4 text-amber-500" />
                최종 승자 · {winnerText}
              </div>
              <div className="text-xs font-black text-amber-700">총 {winningScore}점</div>
            </div>
          )}
          <div className="space-y-2">
            {scores.map((score) => {
              const seatNo = Number(get(score, "seat_no", "seatNo", 0));
              return (
                <div key={seatNo || score.label} className="flex items-center justify-between rounded-xl bg-slate-50 px-3 py-2">
                  <div className="flex items-center gap-2">
                    <TurtleStack seatNos={[seatNo]} />
                    <div>
                      <div className="text-xs font-black text-slate-700">{playerName(seatNo)}</div>
                      <div className="text-[10px] font-bold text-slate-400">
                        알 {(score.cards || []).length}장 · {(score.cards || []).join(", ") || "-"}
                      </div>
                    </div>
                  </div>
                  <div className="flex items-center gap-1 text-sm font-black text-slate-900">
                    {score.winner && <Crown className="h-4 w-4 text-amber-500" />}
                    {score.score}
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        <div className="rounded-[1.5rem] border border-slate-200 bg-white p-4 shadow-lg">
          <div className="mb-3 text-sm font-black text-slate-900">최근 기록</div>
          <div className="space-y-2">
            {moveHistory.slice(-5).reverse().map((move) => (
              <div key={get(move, "turn_number", "turnNumber", 0)} className="rounded-xl bg-slate-50 px-3 py-2 text-xs font-bold text-slate-500">
                {get(move, "turn_number", "turnNumber", 0)} · {maheEventLabels[get(move, "action_type", "actionType", "")] || get(move, "action_type", "actionType", "")} · {playerName(get(move, "active_seat_no", "activeSeatNo", 0))}
                {Number(get(move, "steps", "steps", 0)) > 0 ? ` · ${get(move, "steps", "steps", 0)}칸` : ""}
                {Number(get(move, "value", "value", 0)) > 0 ? ` · ${get(move, "value", "value", 0)}점` : ""}
              </div>
            ))}
            {!moveHistory.length && (
              <TabletopHistoryEmptyState
                game="mahe"
                title="아직 이동 기록이 없습니다"
                detail="첫 주사위 선택이 처리되면 이동 칸, 거북이, 알 카드 흐름이 이 기록 영역에 쌓입니다."
                nextAction="첫 이동"
              />
            )}
          </div>
        </div>
      </aside>
    </div>
    <section data-smoke="mahe-bottom-summary" className="rounded-[1.5rem] border border-slate-200 bg-white p-3 shadow-lg sm:p-4">
      <div className="mb-2 flex flex-wrap items-center justify-between gap-2">
        <div className="text-sm font-black text-slate-900">마헤 흐름 요약</div>
        <div className="rounded-full bg-slate-100 px-2.5 py-1 text-[10px] font-black text-slate-500">하단 참고</div>
      </div>
      <div className="grid gap-2 sm:grid-cols-2 xl:grid-cols-4">
        {maheBottomSummaryItems.map((item) => (
          <div key={item.key} className={`rounded-xl border px-3 py-2 ${item.tone}`} data-smoke="mahe-bottom-summary-item" data-summary-key={item.key}>
            <div className="text-[10px] font-black opacity-70">{item.label}</div>
            <div className="mt-0.5 truncate text-sm font-black">{item.value}</div>
            <div className="mt-0.5 line-clamp-1 text-[10px] font-bold opacity-70">{item.detail}</div>
          </div>
        ))}
      </div>
    </section>
    </>
  );
};

const dalmutiCardPalettes = {
  high: {
    paper: "#fff7ed",
    rim: "#92400e",
    wash: "#fde68a",
    ink: "#1f2937",
    accent: "#dc2626",
    badge: "#78350f",
  },
  mid: {
    paper: "#f0fdfa",
    rim: "#0f766e",
    wash: "#99f6e4",
    ink: "#134e4a",
    accent: "#0ea5e9",
    badge: "#155e75",
  },
  low: {
    paper: "#f8fafc",
    rim: "#475569",
    wash: "#e2e8f0",
    ink: "#334155",
    accent: "#64748b",
    badge: "#1e293b",
  },
  jester: {
    paper: "#312e81",
    rim: "#fbbf24",
    wash: "#a855f7",
    ink: "#f8fafc",
    accent: "#f97316",
    badge: "#fef3c7",
  },
};

const dalmutiMarkPositions = [
  [80, 92],
  [58, 78],
  [102, 78],
  [58, 112],
  [102, 112],
  [80, 130],
  [42, 96],
  [118, 96],
];

const DalmutiCardArt = ({ rank, jester, name, selected }) => {
  const palette = jester
    ? dalmutiCardPalettes.jester
    : rank <= 3
      ? dalmutiCardPalettes.high
      : rank <= 7
        ? dalmutiCardPalettes.mid
        : dalmutiCardPalettes.low;
  const displayRank = jester ? "J" : String(rank || "?");
  const displayName = jester ? "광대" : String(name || dalmutiRankLabel(rank)).slice(0, 7);
  const caption = jester ? "와일드" : rank <= 3 ? "상위 계급" : rank <= 7 ? "중간 계급" : "하위 계급";
  const markCount = jester ? 0 : Math.max(1, Math.min(dalmutiMarkPositions.length, rank || 1));

  return (
    <svg
      data-smoke="dalmuti-card-art"
      viewBox="0 0 160 224"
      className="block w-full"
      style={{ aspectRatio: "5 / 7" }}
      aria-hidden="true"
      focusable="false"
    >
      <rect x="6" y="6" width="148" height="212" rx="18" fill={palette.paper} stroke={selected ? "#0f172a" : palette.rim} strokeWidth={selected ? 5 : 3} />
      <path d="M22 26h116v148c-25 18-54 24-86 16-14-4-24-11-30-20Z" fill={palette.wash} opacity={jester ? 0.42 : 0.58} />
      <path d="M22 32c24 14 48 14 72 0 18-10 34-9 46 2v30c-18-13-36-13-54 0-28 19-55 17-64-5Z" fill="#ffffff" opacity={jester ? 0.14 : 0.55} />
      <rect x="18" y="18" width="38" height="42" rx="10" fill={jester ? "#1e1b4b" : "#ffffff"} opacity={jester ? 0.72 : 0.82} />
      <text x="37" y="46" textAnchor="middle" fontSize="25" fontWeight="900" fill={palette.ink}>{displayRank}</text>
      <rect x="104" y="18" width="38" height="24" rx="12" fill={jester ? palette.badge : "#ffffff"} opacity={jester ? 0.95 : 0.85} />
      <text x="123" y="34" textAnchor="middle" fontSize="11" fontWeight="900" fill={jester ? "#581c87" : palette.badge}>{jester ? "광대" : `${rank}장`}</text>
      {jester ? (
        <g>
          <path d="M43 133c8-36 19-58 35-66 13 12 21 25 25 40 9-23 20-38 34-45 8 33 3 60-15 82-23 16-49 15-79-11Z" fill="#fbbf24" stroke="#1e1b4b" strokeWidth="6" strokeLinejoin="round" />
          <path d="M55 132c9-22 17-37 25-45 10 11 16 25 18 42 9-20 19-33 30-39 0 21-8 38-25 51-17 7-33 5-48-9Z" fill="#f97316" opacity="0.78" />
          <circle cx="78" cy="67" r="9" fill="#fb7185" stroke="#fef3c7" strokeWidth="4" />
          <circle cx="136" cy="62" r="9" fill="#22c55e" stroke="#fef3c7" strokeWidth="4" />
          <circle cx="42" cy="133" r="8" fill="#38bdf8" stroke="#fef3c7" strokeWidth="4" />
        </g>
      ) : (
        <g>
          <path d="M49 142h62l8 24H41Z" fill="#ffffff" opacity="0.72" />
          <path d="M46 144l14-29 21 22 21-22 14 29Z" fill={palette.accent} opacity="0.86" stroke={palette.rim} strokeWidth="3" strokeLinejoin="round" />
          {dalmutiMarkPositions.slice(0, markCount).map(([cx, cy], index) => (
            <g key={`${cx}-${cy}`}>
              {rank <= 3 ? (
                <path d={`M${cx} ${cy - 9}l6 7 9 1-6 6 2 9-11-5-10 5 2-9-7-6 10-1Z`} fill="#ffffff" stroke={palette.rim} strokeWidth="2" opacity={index > 5 ? 0.62 : 0.9} />
              ) : (
                <circle cx={cx} cy={cy} r={rank <= 7 ? 8 : 7} fill="#ffffff" stroke={palette.accent} strokeWidth="3" opacity={index > 5 ? 0.62 : 0.9} />
              )}
            </g>
          ))}
        </g>
      )}
      <rect x="20" y="176" width="120" height="28" rx="14" fill={jester ? "#1e1b4b" : "#ffffff"} opacity={jester ? 0.68 : 0.82} />
      <text x="80" y="195" textAnchor="middle" fontSize="14" fontWeight="900" fill={palette.ink}>{displayName}</text>
      <text x="80" y="213" textAnchor="middle" fontSize="9" fontWeight="800" fill={jester ? "#fde68a" : palette.badge}>{caption}</text>
      {selected && (
        <g>
          <rect x="34" y="65" width="92" height="24" rx="12" fill="#0f172a" opacity="0.9" />
          <text x="80" y="82" textAnchor="middle" fontSize="12" fontWeight="900" fill="#ffffff">선택됨</text>
        </g>
      )}
    </svg>
  );
};

const DalmutiCard = ({ card, selected, onClick, disabled }) => {
  const rank = Number(card?.rank || 0);
  const jester = Boolean(card?.jester);
  const cardName = card?.name || "카드";
  const cardLabel = [
    cardName,
    jester ? "광대 와일드 카드" : `${rank}계급 카드`,
    selected ? "선택됨" : "선택 안 됨",
    disabled ? "현재 선택 불가" : "선택 가능",
  ].join(" · ");
  return (
    <button
      type="button"
      disabled={disabled}
      onClick={onClick}
      aria-label={cardLabel}
      aria-pressed={selected}
      title={cardLabel}
      className={[
        "relative rounded-xl border bg-white p-1.5 text-left shadow-sm transition disabled:opacity-70",
        selected ? "tabletop-selected-card border-slate-950 ring-2 ring-slate-950" : "border-slate-200 hover:-translate-y-1 hover:border-slate-400",
      ].join(" ")}
    >
      <DalmutiCardArt rank={rank} jester={jester} name={cardName} selected={selected} />
    </button>
  );
};

const DalmutiPlayAdvisorArt = ({
  selectedRank = 0,
  selectedCount = 0,
  requiredRank = 0,
  requiredCount = 0,
  legal = false,
  phase = "PLAYING",
}) => {
  const selectedLabel = selectedCount
    ? selectedRank ? dalmutiRankLabel(selectedRank) : "광대"
    : "미선택";
  const requiredLabel = requiredCount
    ? `${dalmutiRankLabel(requiredRank)} ${requiredCount}장`
    : "새 기준";
  const resultFill = legal ? "#dcfce7" : selectedCount ? "#ffe4e6" : "#f8fafc";
  const resultStroke = legal ? "#16a34a" : selectedCount ? "#e11d48" : "#94a3b8";
  const resultText = legal ? "제출 가능" : selectedCount ? "조건 불일치" : "선택 대기";
  const selectedSlots = Array.from({ length: Math.max(1, Math.min(5, selectedCount || requiredCount || 1)) }, (_, index) => index);
  const requiredSlots = Array.from({ length: Math.max(1, Math.min(5, requiredCount || selectedCount || 1)) }, (_, index) => index);

  return (
    <svg
      viewBox="0 0 360 220"
      className="h-full min-h-[150px] w-full"
      role="img"
      aria-label={`달무티 제출 판단, 기준 ${requiredLabel}, 선택 ${selectedLabel} ${selectedCount}장`}
      data-smoke="dalmuti-play-advisor-art"
    >
      <defs>
        <linearGradient id="dalmutiAdvisorWash" x1="0" x2="1" y1="0" y2="1">
          <stop offset="0" stopColor="#f5f3ff" />
          <stop offset="0.55" stopColor="#ffffff" />
          <stop offset="1" stopColor="#ecfeff" />
        </linearGradient>
      </defs>
      <rect x="14" y="14" width="332" height="192" rx="28" fill="url(#dalmutiAdvisorWash)" stroke="#ffffff" strokeWidth="3" />
      <path d="M72 155c35-56 83-84 144-84 32 0 60 8 84 24" fill="none" stroke="#ddd6fe" strokeWidth="14" strokeLinecap="round" />
      <path d="M74 155c36-46 83-69 142-69 33 0 61 8 84 24" fill="none" stroke="#7c3aed" strokeWidth="5" strokeLinecap="round" opacity="0.62" />
      <g>
        <rect x="42" y="56" width="104" height="76" rx="18" fill="#312e81" opacity="0.12" />
        <rect x="34" y="48" width="116" height="88" rx="18" fill="#ffffff" stroke="#c4b5fd" strokeWidth="3" />
        <text x="92" y="72" textAnchor="middle" fontSize="12" fontWeight="900" fill="#6d28d9">현재 기준</text>
        <text x="92" y="98" textAnchor="middle" fontSize="18" fontWeight="900" fill="#312e81">{requiredLabel}</text>
        <g>
          {requiredSlots.map((slot) => (
            <rect key={slot} x={58 + slot * 13} y="111" width="24" height="32" rx="6" fill="#ede9fe" stroke="#7c3aed" strokeWidth="2" opacity={slot < requiredCount || !requiredCount ? 1 : 0.42} />
          ))}
        </g>
      </g>
      <g>
        <rect x="218" y="56" width="104" height="76" rx="18" fill="#312e81" opacity="0.12" />
        <rect x="210" y="48" width="116" height="88" rx="18" fill="#ffffff" stroke={resultStroke} strokeWidth="3" />
        <text x="268" y="72" textAnchor="middle" fontSize="12" fontWeight="900" fill="#0f766e">선택 묶음</text>
        <text x="268" y="98" textAnchor="middle" fontSize="18" fontWeight="900" fill="#0f172a">{selectedLabel}</text>
        <g>
          {selectedSlots.map((slot) => (
            <rect key={slot} x={234 + slot * 13} y="111" width="24" height="32" rx="6" fill={resultFill} stroke={resultStroke} strokeWidth="2" opacity={slot < selectedCount || !selectedCount ? 1 : 0.42} />
          ))}
        </g>
      </g>
      <g>
        <circle cx="180" cy="92" r="30" fill={resultFill} stroke={resultStroke} strokeWidth="4" />
        <path d={legal ? "M166 92l10 10 20-23" : "M168 80l24 24M192 80l-24 24"} fill="none" stroke={legal ? "#16a34a" : selectedCount ? "#e11d48" : "#64748b"} strokeWidth="6" strokeLinecap="round" strokeLinejoin="round" />
      </g>
      <rect x="92" y="164" width="176" height="34" rx="17" fill={resultFill} stroke={resultStroke} strokeWidth="3" />
      <text x="180" y="186" textAnchor="middle" fontSize="14" fontWeight="900" fill={legal ? "#166534" : selectedCount ? "#be123c" : "#475569"}>{phase === "FINISHED" ? "결과 확인" : resultText}</text>
    </svg>
  );
};

const DalmutiPlayAdvisorPanel = ({
  phase,
  canPlay,
  canReturnTax,
  canDecideRevolution,
  selectedCards = [],
  selectedPlayStatus,
  currentTrick,
  currentTrickCount = 0,
  currentTrickRank = 0,
  handRankGroups = [],
  pendingTaxCount = 0,
  passCount = 0,
  requiredPassCount = 0,
  taxProgressText = "",
  selectionHint = "",
  trickClearHint = "",
}) => {
  const normalSelectedCards = selectedCards.filter((card) => !card.jester);
  const selectedRank = normalSelectedCards.length ? Number(normalSelectedCards[0].rank || 0) : 0;
  const selectedCount = selectedCards.length;
  const jokerCount = handRankGroups.find((group) => group.jester)?.cards.length || 0;
  const requiredCount = currentTrick ? currentTrickCount : 0;
  const requiredRank = currentTrick ? currentTrickRank : 0;
  const candidateGroups = handRankGroups
    .filter((group) => !group.jester)
    .filter((group) => {
      if (phase !== "PLAYING") return false;
      if (!currentTrick) return group.cards.length > 0;
      return group.rank < currentTrickRank && group.cards.length + jokerCount >= currentTrickCount;
    });
  const bestCandidate = candidateGroups[0];
  const legal = Boolean(phase === "PLAYING" && canPlay && selectedPlayStatus?.legal);
  const advisorMode = phase === "TAX_RETURN"
    ? "세금 반환"
    : phase === "REVOLUTION_DECISION"
      ? "혁명 판단"
      : phase === "FINISHED"
        ? "결과 확인"
        : canPlay
          ? "제출 판단"
          : "차례 대기";
  const selectedLabel = selectedCount
    ? `${selectedRank ? dalmutiRankLabel(selectedRank) : "광대"} ${selectedCount}장`
    : "선택 없음";
  const criteriaText = phase === "TAX_RETURN"
    ? `${pendingTaxCount}장 반환 필요`
    : currentTrick
      ? `${dalmutiRankLabel(currentTrickRank)} ${currentTrickCount}장보다 높은 같은 장수`
      : "같은 계급 여러 장으로 새 기준 생성";
  const candidateText = bestCandidate
    ? `${bestCandidate.label} ${Math.min(bestCandidate.cards.length, currentTrickCount || bestCandidate.cards.length)}장`
    : phase === "PLAYING" ? "즉시 후보 없음" : advisorMode;
  const guideItems = [
    {
      label: "제출 기준",
      value: criteriaText,
      detail: currentTrick ? trickClearHint : "기준이 없으면 같은 계급 묶음으로 새 흐름을 열 수 있습니다.",
      tone: "border-violet-100 bg-violet-50 text-violet-800",
    },
    {
      label: "선택 묶음",
      value: selectedLabel,
      detail: selectionHint || selectedPlayStatus?.reason || "카드를 선택하면 제출 가능 여부가 여기서 분해됩니다.",
      tone: selectedCount ? (selectedPlayStatus?.legal ? "border-emerald-100 bg-emerald-50 text-emerald-800" : "border-rose-100 bg-rose-50 text-rose-800") : "border-slate-100 bg-white text-slate-700",
    },
    {
      label: "빠른 후보",
      value: candidateText,
      detail: jokerCount ? `광대 ${jokerCount}장은 부족한 장수를 보탤 수 있습니다.` : "현재 손패의 계급 묶음을 기준으로 계산했습니다.",
      tone: bestCandidate ? "border-cyan-100 bg-cyan-50 text-cyan-800" : "border-slate-100 bg-white text-slate-600",
    },
    {
      label: phase === "TAX_RETURN" ? "반환 진행" : "패스 압력",
      value: phase === "TAX_RETURN" ? taxProgressText : currentTrick ? `${passCount}/${requiredPassCount}` : "새 기준",
      detail: phase === "REVOLUTION_DECISION" ? "광대 2장을 가진 플레이어의 혁명 선언 단계입니다." : phase === "TAX_RETURN" ? "세금 반환이 끝나야 라운드가 진행됩니다." : "모두 패스하면 현재 기준이 정리되고 다음 기준으로 넘어갑니다.",
      tone: "border-amber-100 bg-amber-50 text-amber-800",
    },
  ];

  return (
    <section data-smoke="dalmuti-play-advisor-panel" className="mt-4 rounded-2xl border border-violet-100 bg-gradient-to-br from-violet-50 via-white to-cyan-50 p-3 shadow-sm sm:rounded-[1.5rem] sm:p-4">
      <div className="grid gap-3 lg:grid-cols-[minmax(220px,0.78fr)_minmax(0,1fr)]">
        <div className="min-h-[170px]">
          <DalmutiPlayAdvisorArt
            selectedRank={selectedRank}
            selectedCount={selectedCount}
            requiredRank={requiredRank}
            requiredCount={requiredCount}
            legal={legal}
            phase={phase}
          />
        </div>
        <div className="min-w-0">
          <div className="flex flex-wrap items-center justify-between gap-2">
            <div>
              <div className="text-[11px] font-black uppercase text-violet-700">Dalmuti Play Advisor</div>
              <h3 className="text-base font-black text-slate-900">카드 제출 판단</h3>
            </div>
            <div className={`rounded-full border px-3 py-1 text-[11px] font-black ${legal || canReturnTax || canDecideRevolution ? "border-emerald-100 bg-emerald-50 text-emerald-700" : "border-slate-200 bg-white text-slate-600"}`}>
              {advisorMode}
            </div>
          </div>
          <div className="mt-3 grid gap-2 sm:grid-cols-2">
            {guideItems.map((item) => (
              <div key={item.label} data-smoke="dalmuti-play-advisor-item" className={`rounded-xl border px-3 py-2.5 ${item.tone}`}>
                <div className="text-[10px] font-black opacity-70">{item.label}</div>
                <div className="mt-0.5 text-sm font-black leading-snug">{item.value}</div>
                <div className="mt-1 text-[11px] font-bold leading-relaxed opacity-80">{item.detail}</div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
};

const DalmutiRankPressureArt = ({ rows = [], activeSeatNo = 0, leadSeatNo = 0, maxHandCount = 12 }) => {
  const safeMax = Math.max(1, Number(maxHandCount) || 12);
  const visibleRows = rows.slice(0, 6);
  const laneStart = 112;
  const laneWidth = 228;

  return (
    <svg
      viewBox="0 0 420 236"
      className="h-full min-h-[170px] w-full"
      role="img"
      aria-label="달무티 손패 소진과 계급 압력"
      data-smoke="dalmuti-rank-pressure-art"
    >
      <rect x="14" y="14" width="392" height="208" rx="26" fill="#faf5ff" stroke="#ddd6fe" strokeWidth="3" />
      <path d="M44 190h316" stroke="#c4b5fd" strokeWidth="5" strokeLinecap="round" />
      <path d="M340 78v118" stroke="#7c3aed" strokeWidth="3" strokeLinecap="round" strokeDasharray="5 6" />
      <text x="337" y="68" textAnchor="middle" fontSize="11" fontWeight="900" fill="#6d28d9">0장</text>
      <rect x="30" y="28" width="182" height="38" rx="15" fill="#ffffff" stroke="#c4b5fd" strokeWidth="2" />
      <text x="46" y="52" fontSize="13" fontWeight="900" fill="#6d28d9">손패 레이스</text>
      <text x="134" y="52" fontSize="10" fontWeight="800" fill="#64748b">먼저 비우면 다음 계급 상승</text>

      {visibleRows.map((row, index) => {
        const y = 86 + index * 28;
        const remainingRatio = Math.max(0, Math.min(1, Number(row.handCount || 0) / safeMax));
        const progress = row.outOrder ? 1 : Math.max(0.08, 1 - remainingRatio);
        const barWidth = progress * laneWidth;
        const active = Number(row.seatNo) === Number(activeSeatNo);
        const lead = Number(row.seatNo) === Number(leadSeatNo);
        const mine = Boolean(row.isMe);
        const fill = row.outOrder ? "#16a34a" : active ? "#f59e0b" : mine ? "#0284c7" : lead ? "#7c3aed" : "#64748b";
        return (
          <g key={row.seatNo || index} data-smoke="dalmuti-rank-pressure-node">
            <text x="34" y={y + 5} fontSize="11" fontWeight="900" fill={fill}>{row.name}</text>
            <rect x={laneStart} y={y - 8} width={laneWidth} height="13" rx="7" fill="#e9d5ff" opacity="0.8" />
            <rect x={laneStart} y={y - 8} width={barWidth} height="13" rx="7" fill={fill} opacity="0.78" />
            <circle cx={laneStart + barWidth} cy={y - 1.5} r={active ? 8 : 6} fill="#ffffff" stroke={fill} strokeWidth={active ? 4 : 3} />
            <text x={laneStart + barWidth} y={y + 3} textAnchor="middle" fontSize="8" fontWeight="900" fill={fill}>{row.seatNo}</text>
            <text x="382" y={y + 5} textAnchor="end" fontSize="10" fontWeight="900" fill="#475569">
              {row.outOrder ? `${row.outOrder}등` : `${row.handCount}장`}
            </text>
          </g>
        );
      })}
      <rect x="246" y="28" width="110" height="38" rx="15" fill="#ffffff" stroke="#7c3aed" strokeWidth="2" />
      <text x="301" y="52" textAnchor="middle" fontSize="12" fontWeight="900" fill="#5b21b6">계급 압력</text>
    </svg>
  );
};

const DalmutiRankPressurePanel = ({
  rows = [],
  phase = "PLAYING",
  activeSeatNo = 0,
  leadSeatNo = 0,
  passCount = 0,
  requiredPassCount = 0,
  currentTrickLabel = "새 기준",
  nextLeaderName = "",
}) => {
  const activeRow = rows.find((row) => Number(row.seatNo) === Number(activeSeatNo));
  const leadRow = rows.find((row) => Number(row.seatNo) === Number(leadSeatNo));
  const me = rows.find((row) => row.isMe);
  const raceLeader = rows
    .filter((row) => !row.outOrder)
    .slice()
    .sort((left, right) => Number(left.handCount || 0) - Number(right.handCount || 0) || Number(left.orderIndex || 0) - Number(right.orderIndex || 0))[0]
    || rows.find((row) => row.outOrder);
  const maxHandCount = Math.max(1, ...rows.map((row) => Number(row.handCount || 0)));
  const finishedCount = rows.filter((row) => row.outOrder).length;
  const passText = requiredPassCount > 0 ? `${passCount}/${requiredPassCount}` : "새 기준";
  const items = [
    {
      label: "손패 레이스",
      value: raceLeader ? `${raceLeader.name} ${raceLeader.outOrder ? `${raceLeader.outOrder}등` : `${raceLeader.handCount}장`}` : "대기",
      detail: me ? `내 손패 ${me.handCount}장 · 먼저 비우면 다음 계급 순서가 올라갑니다.` : "플레이어별 남은 장수를 같은 축으로 비교합니다.",
      tone: "border-violet-100 bg-violet-50 text-violet-800",
    },
    {
      label: "현재 선",
      value: leadRow ? leadRow.name : activeRow?.name || "대기",
      detail: `현재 기준: ${currentTrickLabel}`,
      tone: "border-cyan-100 bg-cyan-50 text-cyan-800",
    },
    {
      label: "패스 압력",
      value: passText,
      detail: requiredPassCount > 0 ? "필요 패스가 채워지면 기준이 정리되고 새 기준으로 넘어갑니다." : "기준이 없으면 차례 플레이어가 새 묶음을 열 수 있습니다.",
      tone: requiredPassCount > 0 && passCount >= requiredPassCount ? "border-emerald-100 bg-emerald-50 text-emerald-800" : "border-amber-100 bg-amber-50 text-amber-800",
    },
    {
      label: phase === "FINISHED" ? "다음 계급" : "완료 현황",
      value: phase === "FINISHED" && nextLeaderName ? `${nextLeaderName} 다음 대달무티` : `${finishedCount}/${rows.length}명 완료`,
      detail: "라운드 결과가 다음 손의 계급 순서로 이어집니다.",
      tone: phase === "FINISHED" ? "border-emerald-100 bg-emerald-50 text-emerald-800" : "border-slate-100 bg-white text-slate-700",
    },
  ];

  return (
    <section data-smoke="dalmuti-rank-pressure-panel" className="mt-4 overflow-hidden rounded-2xl border border-violet-100 bg-gradient-to-br from-violet-50 via-white to-slate-50 p-3 shadow-sm sm:rounded-[1.5rem] sm:p-4">
      <div className="grid gap-3 lg:grid-cols-[minmax(220px,0.8fr)_minmax(0,1fr)]">
        <div className="min-h-[176px]">
          <DalmutiRankPressureArt rows={rows} activeSeatNo={activeSeatNo} leadSeatNo={leadSeatNo} maxHandCount={maxHandCount} />
        </div>
        <div className="min-w-0">
          <div className="flex flex-wrap items-start justify-between gap-2">
            <div>
              <div className="text-[11px] font-black text-violet-700">계급 압력</div>
              <h3 className="text-base font-black text-slate-900">누가 먼저 손패를 비우는지 확인</h3>
            </div>
            <div className="rounded-full border border-violet-100 bg-white px-3 py-1 text-[11px] font-black text-violet-700">
              {rows.length}명 레이스
            </div>
          </div>
          <div className="mt-3 grid gap-2 sm:grid-cols-2">
            {items.map((item) => (
              <div key={item.label} data-smoke="dalmuti-rank-pressure-item" className={`rounded-xl border px-3 py-2.5 ${item.tone}`}>
                <div className="text-[10px] font-black opacity-70">{item.label}</div>
                <div className="mt-0.5 text-sm font-black leading-snug">{item.value}</div>
                <div className="mt-1 text-[11px] font-bold leading-relaxed opacity-80">{item.detail}</div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
};

const DalmutiEmptyHandArt = ({
  phaseLabel = "",
  outOrder = 0,
  activeName = "",
  nextLeaderName = "",
  passText = "",
}) => {
  const completed = Number(outOrder || 0) > 0;
  const activeLabel = String(activeName || "대기").slice(0, 5);
  const leaderLabel = String(nextLeaderName || "대기").slice(0, 5);
  const statusLabel = completed ? `${outOrder}등` : "대기";
  const nodes = [
    { label: "손패", value: "0장", x: 72, y: 90, fill: "#0f766e", bg: "#ccfbf1" },
    { label: "순위", value: statusLabel, x: 168, y: 140, fill: completed ? "#16a34a" : "#64748b", bg: completed ? "#dcfce7" : "#f8fafc" },
    { label: "차례", value: activeLabel, x: 270, y: 90, fill: "#7c3aed", bg: "#ede9fe" },
    { label: "다음", value: leaderLabel, x: 342, y: 144, fill: "#0369a1", bg: "#e0f2fe" },
  ];

  return (
    <svg
      viewBox="0 0 420 230"
      className="h-full min-h-[170px] w-full"
      role="img"
      aria-label={`달무티 빈 손패 안내, ${phaseLabel}, ${completed ? `${outOrder}등 완료` : "순위 대기"}`}
      data-smoke="dalmuti-empty-hand-art"
    >
      <rect x="14" y="14" width="392" height="208" rx="26" fill="#f0fdfa" stroke="#99f6e4" strokeWidth="3" />
      <path d="M68 156c50-62 112-76 188-44 38 16 70 18 100 6" fill="none" stroke="#bae6fd" strokeWidth="16" strokeLinecap="round" />
      <path d="M70 156c50-51 111-61 184-32 38 15 70 16 99 3" fill="none" stroke="#0f766e" strokeWidth="5" strokeLinecap="round" opacity="0.68" />
      <rect x="34" y="30" width="184" height="40" rx="16" fill="#ffffff" stroke="#5eead4" strokeWidth="2" />
      <text x="52" y="55" fontSize="13" fontWeight="900" fill="#0f766e">손패 완료</text>
      <text x="134" y="55" fontSize="10" fontWeight="800" fill="#64748b">{phaseLabel}</text>
      <rect x="238" y="30" width="116" height="40" rx="16" fill="#ffffff" stroke="#bfdbfe" strokeWidth="2" />
      <text x="296" y="55" textAnchor="middle" fontSize="11" fontWeight="900" fill="#0369a1">패스 {passText || "대기"}</text>
      {nodes.map((node) => (
        <g key={node.label} data-smoke="dalmuti-empty-hand-node">
          <circle cx={node.x + 5} cy={node.y + 7} r="30" fill={node.fill} opacity="0.12" />
          <rect x={node.x - 34} y={node.y - 24} width="78" height="56" rx="18" fill="#ffffff" stroke={node.fill} strokeWidth="3" />
          <rect x={node.x - 24} y={node.y - 16} width="58" height="18" rx="9" fill={node.bg} />
          <text x={node.x + 5} y={node.y - 2} textAnchor="middle" fontSize="10" fontWeight="900" fill={node.fill}>{node.label}</text>
          <text x={node.x + 5} y={node.y + 20} textAnchor="middle" fontSize="13" fontWeight="900" fill="#0f172a">{node.value}</text>
        </g>
      ))}
    </svg>
  );
};

const DalmutiEmptyHandPanel = ({
  phase = "PLAYING",
  phaseLabel = "",
  outOrder = 0,
  activeName = "",
  nextLeaderName = "",
  currentTrickLabel = "새 기준",
  passCount = 0,
  requiredPassCount = 0,
  turnNotice = "",
  trickClearHint = "",
  nextOrderText = "",
}) => {
  const completed = Number(outOrder || 0) > 0;
  const passText = requiredPassCount > 0 ? `${passCount}/${requiredPassCount}` : "새 기준";
  const positionValue = completed
    ? `${outOrder}등으로 손패 완료`
    : phase === "FINISHED" ? "결과 확정 대기" : "순위 확정 대기";
  const flowValue = phase === "FINISHED" ? "결과 확인" : activeName ? `${activeName} 차례` : phaseLabel;
  const nextValue = phase === "FINISHED" && nextLeaderName ? `${nextLeaderName} 다음 대달무티` : "관전 대기";
  const items = [
    {
      label: "손패 상태",
      value: "모두 제출 완료",
      detail: "남은 카드가 없어 추가 제출은 없습니다.",
      tone: "border-emerald-100 bg-emerald-50 text-emerald-800",
    },
    {
      label: "이번 손 위치",
      value: positionValue,
      detail: completed ? "손패를 비운 순서가 다음 계급 순서에 반영됩니다." : "서버가 아웃 순서를 확정하면 결과 영역에 반영됩니다.",
      tone: completed ? "border-teal-100 bg-teal-50 text-teal-800" : "border-slate-100 bg-white text-slate-700",
    },
    {
      label: "현재 흐름",
      value: flowValue,
      detail: phase === "FINISHED" ? nextOrderText || "다음 손 계급 순서를 확인하세요." : `${currentTrickLabel} · 패스 ${passText}`,
      tone: "border-violet-100 bg-violet-50 text-violet-800",
    },
    {
      label: "다음 행동",
      value: nextValue,
      detail: phase === "FINISHED" ? "결과와 다음 손 계급을 확인하고 새 라운드를 기다리세요." : trickClearHint || turnNotice || "현재 기준과 패스 흐름을 지켜보면 됩니다.",
      tone: "border-cyan-100 bg-cyan-50 text-cyan-800",
    },
  ];

  return (
    <section
      data-smoke="dalmuti-empty-hand-panel"
      data-phase={phase}
      data-out-order={outOrder || ""}
      data-pass-progress={passText}
      className="col-span-full overflow-hidden rounded-2xl border border-emerald-100 bg-gradient-to-br from-emerald-50 via-white to-violet-50 p-3 sm:p-4"
      role="status"
      aria-live="polite"
      aria-atomic="true"
    >
      <div className="grid gap-3 lg:grid-cols-[minmax(210px,0.74fr)_minmax(0,1fr)]">
        <div className="min-h-[170px]">
          <DalmutiEmptyHandArt
            phaseLabel={phaseLabel}
            outOrder={outOrder}
            activeName={activeName}
            nextLeaderName={nextLeaderName}
            passText={passText}
          />
        </div>
        <div className="min-w-0">
          <div className="flex flex-wrap items-start justify-between gap-2">
            <div>
              <div className="text-[11px] font-black text-emerald-700">손패 0장</div>
              <h3 className="text-base font-black text-slate-900">손패 완료 상태</h3>
            </div>
            <div className="rounded-full border border-emerald-100 bg-white px-3 py-1 text-[11px] font-black text-emerald-700">
              {phaseLabel}
            </div>
          </div>
          <div className="mt-3 grid gap-2 sm:grid-cols-2">
            {items.map((item) => (
              <div key={item.label} data-smoke="dalmuti-empty-hand-item" className={`rounded-xl border px-3 py-2.5 ${item.tone}`}>
                <div className="text-[10px] font-black opacity-70">{item.label}</div>
                <div className="mt-0.5 text-sm font-black leading-snug">{item.value}</div>
                <div className="mt-1 text-[11px] font-bold leading-relaxed opacity-80">{item.detail}</div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
};

